(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["fr"] = {"ui":{"lead":"Comment les jeux ont-ils été retrouvés, oubliés, déchiffrés et transformés ? Lisez {n} histoires et répondez juste à toutes les questions du quiz final pour gagner un tampon.","card":"Carte de tampons","cardN":"{n} sur {of} obtenus","cardAll":"Tous obtenus !","no":"Histoire {n}","mins":"{n} min","stamped":"Tamponné","back":"Toutes les histoires","quiz":"Petit quiz","links":"Voir et jouer","game":"Jeu","exhibit":"Collection","art":"Œuvre","room":"Salle","room_chance":"Hasard","qn":"Question {n} sur {of}","right":"Bravo !","wrong":"Raté… la bonne réponse est indiquée.","got":"Tamponné !","again":"Tout juste !","gotSub":"Il figure sur votre carte de tampons.","missed":"{n} erreur(s)","retrySub":"Il faut tout réussir pour obtenir le tampon. Relisez l’histoire et réessayez.","retry":"Réessayer","room_paint":"Dans l’art","room_map":"Carte","kfH":"L’essentiel","tlH":"Chronologie","refH":"Sources et lectures","picLink":"ouvre la page du musée"},"ex":{"ur":"Plateau du jeu royal d’Ur","liubo":"Plateau et pions de liubo","pyrgus":"Tour à dés romaine","sugoroku":"Plateau de sugoroku du Shōsōin","nishapur":"Échecs de Nichapur","lewis":"Échecs de Lewis","senet":"Coffret de senet de Toutânkhamon","ballinderry":"Plateau de Ballinderry","goose":"Plateau d’échecs et de jeu de l’oie","kofukuji":"Pièces de shogi du Kōfuku-ji","shosoin":"Goban du Shōsōin"},"paint":{"liubo":"Deux joueurs de liubo","sugoroku":"Deux jeunes filles jouant au sugoroku","shahnama":"Bozorgmehr perce le secret des échecs","nefertari":"La reine Néfertari jouant au senet","chaupar":"Shiva et Parvati jouant au chaupar","shogi":"Jeune couple jouant au shogi","hydria":"Achille et Ajax jouant à un jeu de plateau (hydrie)","eakins":"Les Joueurs d’échecs","weiqi":"Plat aux immortels jouant au weiqi","webb":"Les joueurs de backgammon (cabinet)","liberale":"Les Joueurs d’échecs","mirror":"Valve de miroir : couple jouant aux échecs","morris":"Un tablier de jeu (la marelle)","leifeng":"Jeu de plateau de la pagode Leifeng","teniers":"Partie de trictrac","imari":"Plat à deux joueurs de go","shoei":"Les Quatre Arts","tutinama":"Le singe mord le prince, son partenaire d’échecs (moghol, vers 1560)","ingram":"Le Jeu d’échets chinois","umaya":"Paravent des écuries (go et shogi sur la véranda)","kiyohiro":"Joueuses de sugoroku","vuillard":"La Partie de dames (de Paysages et Intérieurs)","kangra":"Couple jouant au chaupar sur une terrasse","posada":"Le Jeu de l’oie","jintile":"Carreau à décor de femmes jouant à un jeu de plateau","pvl":"Hommes jouant aux dés"},"ur":{"title":"Comment un jeu vieux de 4 500 ans a retrouvé ses règles","lead":"Le plateau des tombes royales d’Ur n’avait pas de mode d’emploi. L’indice se trouvait sur une tablette écrite deux mille ans plus tard.","s":["Dans les années 1920, Leonard Woolley fouille les tombes royales d’Ur, dans le sud de l’Irak, et y trouve un plateau de vingt cases incrusté de coquillage et de lapis-lazuli, daté d’environ 2600–2400 av. J.-C. Des plateaux semblables ont été retrouvés dans tout le Proche-Orient : le jeu fut joué largement et longtemps.","Mais rien n’expliquait comment y jouer. Un plateau, des pions, des dés — et pas de règles : un problème courant avec les jeux anciens.","L’indice dormait dans les réserves du British Museum : une tablette cunéiforme copiée en 177/176 av. J.-C. par le scribe babylonien Itti-Marduk-balāṭu, d’après une tablette appartenant à un certain Iddin-Bēl. Elle fut écrite plus de deux mille ans après le plateau.","Au début des années 1980, Irving Finkel, du British Museum, comprend que la tablette décrit le même jeu de vingt cases. Son revers montre le plateau, avec des présages pour chaque case où l’on s’arrête. À partir de la tablette et du plateau lui-même, Finkel reconstitue un jeu de course pour deux joueurs.","Sa reconstitution se joue aujourd’hui dans le monde entier. Nul ne peut dire si l’on jouait exactement ainsi à Ur. Pourtant, un jeu semblable se jouait encore à Kochi, dans le sud de l’Inde, jusque dans les années 1950 : signe de la longue vie de ce jeu."],"quiz":[["Quand fut écrite la tablette qui a livré les règles ?","Au IIe siècle av. J.-C., plus de 2 000 ans après le plateau","Vers 2600 av. J.-C., comme le plateau","Au Moyen Âge (XIIe siècle)","Au XIXe siècle"],["Qui a déchiffré la tablette et reconstitué les règles ?","Irving Finkel","Howard Carter","Jean-François Champollion","Arthur Evans"],["Que dit la tablette des cases où l’on s’arrête ?","Des présages, bons ou mauvais","Des noms de rois","Des montants d’impôts","Seulement des noms d’étoiles"]],"kf":["Les plateaux datent d’environ 2600–2400 av. J.-C. et viennent des tombes royales d’Ur, dans le sud de l’Irak","Les règles ont été reconstituées d’après une tablette écrite plus de 2 000 ans plus tard","20 cases, sept pions par camp, des dés à quatre faces"],"more":[{"h":"Tombes royales et « jeu royal »","p":["Woolley a trouvé dans le cimetière royal d’Ur non pas un, mais plusieurs plateaux de vingt cases. Le plus célèbre, au British Museum, est en bois incrusté de coquillage, de calcaire rouge et de lapis-lazuli ; il a donné au jeu son nom de « jeu royal d’Ur ».","Ce n’était pourtant pas un jeu réservé aux rois. Les mêmes plateaux apparaissent de la Mésopotamie à l’Égypte et à la Méditerranée orientale, et dans un palais assyrien un plateau a même été gravé sur le socle d’un grand taureau ailé à tête humaine gardant une porte — sans doute par les gardes."],"cap":["Le jeu royal d’Ur du British Museum — à faire tourner en 3D dans la salle Collection"]},{"h":"Comment fonctionne le plateau","p":["Les vingt cases forment un bloc de douze (3×4) et un bloc de six (3×2) reliés par un étroit « pont » de deux. Cinq cases portent une rosette ; dans les règles reconstituées, s’y arrêter donne un nouveau lancer et une case où l’on ne peut pas être pris.","Les dés sont des tétraèdres dont deux pointes sur quatre sont marquées. On en lance quatre et l’on avance du nombre de pointes marquées tournées vers le haut : de 0 à 4. Le 2 est le plus fréquent (6 fois sur 16) ; 0 et 4 ne sortent qu’une fois sur 16. Vous pouvez les lancer dans la salle « Hasard » du musée."],"cap":["Les vingt cases et les cinq rosettes. Les numéros verts suivent le chemin d’un joueur, case par case (règles reconstituées)","Comment tombent quatre dés tétraédriques (sur 16 cas également probables)"]},{"h":"Ce que dit la tablette","p":["Le recto explique le jeu ; le verso dessine le plateau avec des signes du zodiaque dans les cases. Les phrases associées aux cases ressemblent à des présages — « tu trouveras un ami », « tu boiras de la bonne bière » — : le jeu était lié à la chance.","Mais la tablette est en partie brisée et toutes les règles ne se lisent pas. La reconstitution de Finkel assemble le jeu le plus cohérent à partir des lignes lisibles et de la forme du plateau ; d’autres chercheurs ont proposé d’autres versions."]},{"h":"Les derniers joueurs, en Inde","p":["Finkel a appris ensuite que la communauté juive de Kochi (Cochin), dans le sud de l’Inde, jouait encore récemment à un jeu de vingt cases sur un plateau de forme très proche.","Il s’est transmis dans les familles jusqu’à leur départ pour Israël dans les années 1950. Le jeu a peut-être gagné l’Inde par d’anciennes routes commerciales et survécu plus de quatre mille ans."]}],"tl":[["v. 2600–2400 av. J.-C.","Des plateaux de vingt cases sont déposés dans les tombes royales d’Ur"],["VIIIe s. av. J.-C.","Un plateau est gravé sur le socle d’un gardien de porte d’un palais assyrien"],["177/176 av. J.-C.","Un scribe babylonien copie la tablette des règles"],["1922–1934","Woolley fouille Ur et trouve les plateaux"],["Début des années 1980","Finkel lit la tablette et reconstitue les règles"],["Jusqu’aux années 1950","Un jeu très proche se joue à Kochi, dans le sud de l’Inde"]]},"liubo":{"title":"Pourquoi le liubo a-t-il disparu ?","lead":"Sous les Han, de l’empereur au peuple, tout le monde y jouait. En quelques siècles, même ses règles furent oubliées.","s":["Le liubo fut l’engouement de la Chine des Han (206 av. J.-C. – 220 apr. J.-C.). On le voit sur des figurines funéraires, des reliefs sculptés et jusque sur le décor des miroirs, et des immortels y sont souvent représentés en train d’y jouer.","Après la chute des Han, le liubo déclina vite et, semble-t-il, ses règles étaient perdues dès la dynastie Tang. On ignore pourquoi ; selon une hypothèse, les joueurs se sont tournés vers d’autres jeux comme le weiqi (go).","Restèrent les plateaux et les accessoires. Les plateaux portent un motif caractéristique en forme de T, L et V, et les coups se décidaient probablement en lançant de fines baguettes. Le même motif orne les miroirs dits « TLV ».","Les indices écrits s’accumulent aussi peu à peu. En 1993, une tombe Han de Yinwan (Jiangsu) a livré un texte divinatoire utilisant le diagramme du plateau. La tombe de Liu He, marquis de Haihun, fouillée dans les années 2010, a livré plus d’un millier de lattes de bambou sur le liubo, encore à l’étude.","Le liubo de l’Atlas est une reconstitution fondée sur ces indices. Les chercheurs le reconstituent de façons un peu différentes et les vraies règles ne sont pas entièrement connues : de nouvelles découvertes pourraient changer la façon d’y jouer."],"quiz":[["Sous quelle dynastie le liubo fut-il très populaire ?","Han","Ming","Qing","Song"],["Où a-t-on trouvé plus d’un millier de lattes de bambou sur le liubo ?","Dans la tombe de Liu He, marquis de Haihun","Dans le mausolée du Premier Empereur","Dans les grottes de Dunhuang","Dans la Cité interdite"],["Que lançait-on probablement pour décider des coups au liubo ?","De fines baguettes","Un dé à vingt faces","Une toupie","Des cartes illustrées"]],"kf":["Très populaire en Chine des Royaumes combattants aux Han (Ve s. av. J.-C. – IIIe s.)","Un plateau aux lignes en T, L et V ; on lançait de fines baguettes pour avancer","Il déclina vite après la chute des Han et ses règles ne sont toujours pas entièrement connues"],"more":[{"h":"Le plateau TLV","p":["Le plateau de liubo est carré, avec un carré au centre, un T au milieu de chaque côté, des L autour et des V dans les coins. Les pièces devaient avancer sur ces lignes et entre elles.","Les mêmes lignes se retrouvent au dos de miroirs (« miroirs TLV ») et sur des cadrans solaires. Certains chercheurs y lisent une carte du cosmos — ciel, terre et quatre directions —, signe que le liubo était plus qu’un passe-temps."],"cap":["Les lignes d’un plateau de liubo (motif TLV) : un carré central, un T sur chaque côté, des L et des V vers les coins"]},{"h":"Comment on y jouait","p":["La plupart des chercheurs pensent que chaque joueur avait six pièces et lançait de fines baguettes de bambou pour fixer le coup. Le « six » (liu) du nom viendrait de ces six baguettes ou six pièces.","Une pièce qui avançait devenait semble-t-il une puissante « chouette » (xiao). Un poème du IIIe s. av. J.-C. environ, « Rappel de l’âme » des Chants de Chu, dit : « devenue chouette, elle presse et l’on crie “cinq blancs !” ». Des textes décrivent aussi une manière de jouer où l’on pêchait des « poissons » dans l’« eau » au centre du plateau."],"cap":["Deux figurines jouant au liubo, faites pour une tombe Han (Metropolitan Museum of Art)"]},{"h":"Des jeux sortis des tombes","p":["La tombe 3 de Mawangdui, à Changsha (Hunan), vers 168 av. J.-C., contenait un jeu complet — plateau, pièces et baguettes — dans une boîte laquée, pour que le défunt puisse jouer dans l’au-delà.","Les reliefs des murs de tombes montrent souvent des immortels jouant au liubo sur des sommets. Le jeu était lié au monde des immortels et à la longue vie."],"cap":["Le plateau de liubo du musée — à voir en 3D dans la salle Collection"]}],"tl":[["Ve–IIIe s. av. J.-C. (Royaumes combattants)","Des plateaux de liubo commencent à être déposés dans les tombes"],["v. IIIe s. av. J.-C.","« Rappel de l’âme » décrit une partie de liubo"],["v. 168 av. J.-C.","Un jeu complet entre dans la tombe 3 de Mawangdui"],["206 av. J.-C. – 220 (Han)","Joué par empereurs et gens du commun ; sur reliefs et miroirs"],["Tang (VIIe–Xe s.)","On pense que les règles étaient déjà oubliées"],["1993","Un texte divinatoire utilisant le plateau sort des tombes Han de Yinwan"],["Années 2010","Des lattes de bambou sur le liubo apparaissent dans la tombe du marquis de Haihun, Liu He"]]},"zeno":{"title":"Le coup malheureux de l’empereur Zénon","lead":"Il y a mille cinq cents ans, un empereur lança les dés — et le résultat nous est parvenu dans un poème.","s":["Les Romains adoraient la tabula, un jeu de course aux dés sur un plateau de 24 flèches : l’ancêtre du backgammon. Pour empêcher les lancers truqués, on utilisait même des tours à dés, à l’intérieur desquelles les dés dévalaient.","Vers 480, l’empereur romain d’Orient Zénon jouait à la tabula. Ses trois dés donnèrent 2, 5 et 6. Il dut jouer comme l’imposaient les règles, et son jeu se retrouva avec huit pions isolés et sans protection.","La partie fut rapportée par Agathias, historien et poète du VIe siècle qui vécut quelques décennies après Zénon. Son court poème (une épigramme) donne la position des pions : un rare témoignage d’une partie antique.","Au XIXe siècle, le savant français Becq de Fouquières tira du poème la position et les règles : quinze pions chacun et trois dés. Tous les pions partent hors du plateau et les deux joueurs avancent dans le même sens.","Par rapport au backgammon actuel, la tabula se jouait avec trois dés, commençait sans pions sur le plateau et n’avait pas de videau. Grâce à la malchance d’un empereur, nous savons à quoi ressemblait la tabula."],"quiz":[["Qu’a obtenu Zénon ?","2, 5 et 6","6, 6 et 6","1, 1 et 1","3, 4 et 5"],["Qui a rapporté la partie dans un poème ?","Agathias","Homère","Pline","Cicéron"],["Quelle est une différence entre la tabula et le backgammon actuel ?","La tabula utilisait trois dés","Trente pions chacun","Un plateau de 12 flèches","Les pions reculent"]],"kf":["La tabula se jouait sur 24 flèches avec trois dés : un ancêtre du backgammon","La partie de l’empereur Zénon, vers 480, survit avec sa position dans un poème","Les Romains ont même fabriqué des « tours à dés » contre la triche"],"more":[{"h":"Le plateau de la tabula","p":["Le plateau de la tabula, comme celui du backgammon, compte 24 flèches en deux rangées de 12. Chaque joueur avait quinze pions, tous hors du plateau au départ ; selon trois dés, on les entrait, on faisait le tour et on les sortait.","Grande différence avec le backgammon : les deux joueurs vont dans le même sens. Un pion seul pouvait être frappé si l’adversaire tombait sur sa flèche, et devait rentrer de nouveau. Les huit de Zénon étaient justement de ces pions vulnérables."],"cap":["Un plateau de tabula : 24 flèches en deux rangées de 12 ; les pions des deux joueurs vont dans le même sens (flèche)"]},{"h":"Un appareil contre la triche","p":["Les Romains raffolaient des dés. La loi interdisait les jeux d’argent, permis, dit-on, seulement pendant la fête d’hiver des Saturnales — mais les paris ne cessaient pas, ni les tours de main avec les dés.","D’où la tour à dés : les dés jetés en haut rebondissent sur des planchettes et ressortent en bas. Une tour du IVe siècle trouvée dans une villa d’Allemagne porte, ajourée : « Pictes vaincus, ennemi anéanti : jouez tranquilles »."],"cap":["La tour à dés de Vettweiß-Froitzheim (IVe siècle) — à voir en 3D dans la salle Collection"]},{"h":"Les empereurs et les dés","p":["Zénon n’était pas seul. Selon l’historien Suétone, l’empereur Claude, au Ier siècle, aimait tant les dés qu’il écrivit un livre sur cet art et fit aménager sa voiture pour que le plateau ne bouge pas pendant qu’il jouait.","Les sites romains livrent aussi de nombreux plateaux de 36 lettres en mots de six ; chaque lettre tenait lieu de case, et certains portent des moqueries comme « Lève-toi, tu ne sais pas jouer ; laisse la place à un joueur »."],"cap":["Tables et dés plaisaient des empereurs aux soldats (lancez des dés cubiques dans la salle Hasard)"]}],"tl":[["Ier siècle","L’empereur Claude écrit un livre sur les dés"],["IVe siècle","Une tour à dés sert dans une villa d’Allemagne"],["v. 480","La partie malchanceuse de l’empereur Zénon"],["VIe siècle","Agathias met la partie en vers"],["v. Xe siècle","Le poème entre dans l’Anthologie grecque"],["1869","Becq de Fouquières reconstitue la position et les règles"],["1934","R. G. Austin réexamine en détail la partie de Zénon"]]},"sugoroku":{"title":"Le sugoroku interdit","lead":"Les souverains l’interdisaient, on continuait d’y jouer. L’histoire du sugoroku sur plateau au Japon, de l’Antiquité à l’époque d’Edo.","s":["Le trésor du Shōsōin conserve un plateau de sugoroku qui aurait été l’un des favoris de l’empereur Shōmu. Il ne s’agit pas du sugoroku de papier illustré, mais du ban-sugoroku, où l’on déplace des pions blancs et noirs sur un plateau : un parent du backgammon.","Le sugoroku fut très tôt lié aux jeux d’argent. Selon le Nihon shoki, l’impératrice Jitō l’interdit en 689.","Le code Yōrō, appliqué à partir de 757, interdisait aussi le sugoroku aux moines et aux nonnes. Les interdictions furent répétées encore et encore, signe qu’elles n’étaient pas respectées.","À l’époque de Heian, le sugoroku restait populaire ; il apparaît dans les Notes de chevet et le Dit du Genji. Le Dit des Heike raconte que l’empereur retiré Shirakawa citait trois choses qu’il ne pouvait maîtriser : les eaux de la Kamo, les dés du sugoroku et les moines guerriers du mont Hiei.","Les estampes de l’époque d’Edo montrent encore des jeunes filles jouant au ban-sugoroku à l’intérieur. Mais vers l’ère Meiji, le jeu sur plateau avait presque disparu, et « sugoroku » désigna désormais le jeu de papier illustré."],"quiz":[["Le ban-sugoroku, comme le plateau du Shōsōin, est parent de quel jeu ?","Le backgammon","Le shogi","Le go","Les cartes"],["Selon le Nihon shoki, qui interdit le sugoroku en 689 ?","L’impératrice Jitō","L’empereur Shōmu","L’empereur Kanmu","L’empereur Meiji"],["Shirakawa ne maîtrisait ni la Kamo, ni les moines guerriers, ni… quoi ?","Les dés du sugoroku","Les pièces de shogi","Les pierres de go","Un ballon de kemari"]],"kf":["Le ban-sugoroku est un cousin du backgammon, joué au Japon dès le VIIe siècle","Il fut interdit maintes fois à cause des paris, d’abord par l’impératrice Jitō en 689","À l’ère Meiji, il était presque oublié et « sugoroku » désigna le jeu de l’oie illustré sur papier"],"more":[{"h":"Le plateau du Shōsōin","p":["Le plateau du Shōsōin est en palissandre finement marqueté d’ivoire et de bois teintés. Il compte 24 cases, douze de chaque côté, avec des fleurs sur la séparation centrale.","Le Shōsōin conserve aussi de nombreux pions de sugoroku en verre et en pierre. Le ban-sugoroku se joue avec quinze pions blancs et quinze noirs et deux dés : presque le matériel du backgammon. Il serait venu du nard persan par la Chine."],"cap":["Le plateau de sugoroku du Shōsōin, en palissandre marqueté — jouez dessus dans la salle Collection"]},{"h":"Comment on y joue","p":["Chacun dispose quinze pions selon un ordre fixe et avance selon deux dés. Blancs et noirs tournent en sens contraire ; gagne celui qui rassemble le premier tous ses pions dans les six dernières cases.","Un pion seul peut être frappé et renvoyé au départ. Une case qui en porte deux ou plus est interdite à l’adversaire : l’art consiste à bâtir des barrages. Dans la salle Collection, on peut jouer ainsi sur le plateau du Shōsōin."],"cap":["Un plateau de ban-sugoroku (schéma) : les 24 cases, blancs et noirs tournant en sens contraire"]},{"h":"Interdits et modes","p":["Après Jitō, le sugoroku fut encore interdit bien des fois : il y avait toujours des gens pour y perdre leur fortune. Le shogunat de Kamakura promulgua lui aussi des lois contre les paris au sugoroku.","Mais c’était aussi un art d’agrément de la noblesse. Un beau plateau faisait partie du trousseau de la mariée, et l’époque Edo produisit de somptueux plateaux laqués. Haï comme instrument de jeu d’argent, aimé comme trésor : le ban-sugoroku avait les deux visages."],"cap":["Le ban-sugoroku dans une image de l’époque Edo (salle des jeux peints)"]}],"tl":[["VIIe siècle","Le ban-sugoroku arrive de Chine"],["689","L’impératrice Jitō interdit le sugoroku (Nihon shoki)"],["VIIIe siècle","Le plateau marqueté entre au Shōsōin"],["757","Le code Yōrō l’interdit aux moines et nonnes"],["Époque Heian","Il apparaît dans les Notes de chevet et le Dit du Genji"],["XIIe siècle","La plainte de Shirakawa sur « les dés du sugoroku » (Dit des Heike)"],["Époque Edo","De somptueux plateaux pour les trousseaux de mariée"],["Ère Meiji","Le ban-sugoroku n’est presque plus joué"]]},"queen":{"title":"Comment la dame est devenue la pièce la plus forte","lead":"La pièce la plus puissante d’aujourd’hui était au départ un conseiller qui n’avançait que d’une case en diagonale.","s":["Les échecs sont passés de l’Inde à la Perse puis au monde arabe. Dans l’épopée persane du Livre des Rois (Shahnameh), le sage Bozorgmehr résout l’énigme des échecs envoyée d’Inde. Sur ces échiquiers, la pièce voisine du roi était le fers, le conseiller.","Le fers ne se déplaçait que d’une case en diagonale : une pièce très faible. Dans le jeu d’échecs du XIIe siècle de Nichapur, en Iran, c’est un petit trône, plus petit que celui du roi.","En Europe, le conseiller devint une reine ; les échecs de Lewis, au XIIe siècle, comptent des reines. Mais le nouveau nom ne changea pas le déplacement : elle resta faible.","Le grand changement eut lieu en Espagne à la fin du XVe siècle. Scachs d’amor (« Échecs d’amour »), poème écrit à Valence vers 1475, passe pour le plus ancien témoignage de la dame moderne, qui parcourt n’importe quelle distance en ligne, en colonne et en diagonale. Les livres de Lucena (1497) et de Damiano (1512) diffusèrent ensuite la nouvelle règle dans toute l’Europe.","On ne sait pas avec certitude pourquoi la dame devint si forte. Certains pensent que l’on voulait des parties plus rapides ; d’autres évoquent l’influence de reines puissantes comme Isabelle Ire. Quoi qu’il en soit, ce changement rapprocha beaucoup les échecs du jeu actuel."],"quiz":[["Aux échecs persans et arabes, quelle pièce occupait la place de la dame ?","Le fers (conseiller)","L’éléphant","Le char","Le cavalier"],["Comment se déplaçait le fers d’origine ?","D’une case en diagonale","De n’importe quelle distance en ligne droite","En sautant deux cases","Il ne pouvait pas bouger"],["Où fut écrit le poème contenant le plus ancien témoignage de la dame moderne ?","À Valence, au XVe siècle","En Inde, au VIe siècle","À Lewis, au XIIe siècle","À Londres, au XIXe siècle"]],"kf":["La dame est née du « fers » persan et arabe (le conseiller), qui ne bougeait que d’une case en diagonale","La dame forte moderne apparaît par écrit en Espagne vers 1475","Les livres imprimés ont répandu les nouvelles règles en Europe en quelques décennies"],"more":[{"h":"Le faible conseiller","p":["Le fers n’avançait que d’une case en diagonale — rien à voir avec la dame d’aujourd’hui, qui traverse l’échiquier d’un bout à l’autre. Les échecs d’alors étaient lents, et une partie pouvait durer des heures.","L’éléphant (le fou actuel) sautait seulement à la deuxième case en diagonale. Un pion arrivé au dernier rang était promu — mais seulement en ce faible fers."],"cap":["Jusqu’où vont le fers (à gauche) et la dame moderne (à droite)"]},{"h":"« Échecs de la dame » et « échecs enragés »","p":["Avec la nouvelle dame, on appela en Espagne ce jeu « échecs de la dame », et en Italie, pour sa fougue, « scacchi alla rabbiosa » (échecs enragés). À la même époque, le fou put glisser à n’importe quelle distance en diagonale.","Avec des pièces plus fortes, le jeu devint rapide et féroce. Des livres parurent sur les pièges qui gagnent en quelques coups et sur des suites d’ouverture fixes : les échecs devinrent un jeu qu’on étudie."],"cap":["Liberale da Verona, Les Joueurs d’échecs (vers 1475), peint au moment même où naissait la nouvelle dame"]},{"h":"Pourquoi une dame ?","p":["On ne sait pas au juste pourquoi le conseiller devint une dame. Voir la pièce placée près du roi comme son épouse semblait peut-être naturel. En latin, « fers » devint « fercia », puis la pièce fut appelée « regina », la reine.","La raison de sa force est débattue aussi : accélérer les parties, ou l’époque des reines puissantes comme Isabelle Ire de Castille. L’historienne Marilyn Yalom a relié ce changement à la place des femmes au Moyen Âge."],"cap":["La dame des pièces de Lewis (XIIe siècle), au déplacement encore faible"]}],"tl":[["v. VIe siècle","Le chaturanga, ancêtre des échecs, naît en Inde"],["VIIe–IXe siècles","Joué en Perse et dans le monde arabe, avec le fers près du roi"],["v. Xe siècle","Les échecs arrivent en Europe"],["XIIe siècle","Les pièces de Lewis comptent des dames (encore faibles)"],["v. 1475","Le poème valencien Scachs d’amor décrit le nouveau déplacement"],["1497","Le livre d’échecs de Lucena est imprimé en Espagne"],["1512","Le livre de Damiano paraît en Italie et diffuse les règles"]]},"senet":{"title":"Comment le senet devint un voyage vers l’au-delà","lead":"Un jeu pratiqué en Égypte pendant près de trois mille ans finit par représenter le voyage de l’âme après la mort.","s":["Le senet est un jeu de l’Égypte ancienne où des pions avancent sur un plateau de trois rangées de dix cases. Des fragments de ce qui pourrait être des plateaux de senet ont été trouvés dans des tombes de la Ire dynastie, vers 3100 av. J.-C. Les rois jouaient sur de somptueux coffrets, les gens ordinaires sur des plateaux gravés dans la pierre.","Son nom signifie « passage ». À partir du Nouvel Empire (vers 1550 av. J.-C.), le senet fut associé au voyage de l’âme du défunt à travers l’au-delà.","Le chapitre 17 du Livre des morts montre le défunt jouant au senet contre un adversaire invisible. Sur un mur de la tombe de Néfertari, épouse de Ramsès II, la reine est assise devant un plateau de senet.","La tombe de Toutânkhamon contenait au moins cinq coffrets de jeu. L’un d’eux, un grand coffret d’ébène et d’ivoire, porte le senet sur le dessus et un autre jeu de vingt cases sur l’autre face.","Pourtant, aucun texte exposant entièrement les règles n’a été retrouvé. Au XXe siècle, Jéquier, Bell et Kendall (1978), entre autres, ont chacun reconstitué une façon de jouer à partir des plateaux, des images et de fragments de textes. Le senet de l’Atlas est l’une de ces façons fondées sur la recherche."],"quiz":[["Que signifie le nom « senet » ?","Passage","Le jeu du roi","Trente maisons","Traverser le fleuve"],["Au Nouvel Empire, à quoi le senet fut-il associé ?","Au voyage de l’âme dans l’au-delà","À des rites pour la pluie","À des plans de bataille","À des présages de récolte"],["Combien de coffrets de jeu, au moins, dans la tombe de Toutânkhamon ?","Cinq","Un","Deux","Cent"]],"kf":["L’un des plus anciens jeux de plateau : des pions courent sur un plateau de 3 × 10 cases","Son nom signifie « passer » ; au Nouvel Empire, il devint le voyage de l’âme dans l’au-delà","Aucune règle n’a survécu ; les façons de jouer actuelles sont des reconstitutions du XXe siècle"],"more":[{"h":"Trente cases et les cases spéciales","p":["Le plateau de senet compte trois rangées de dix, soit trente cases. Les pions allaient sans doute de gauche à droite sur la première rangée, de droite à gauche sur la deuxième, puis de nouveau de gauche à droite, en dessinant un S.","Les cinq dernières cases portaient souvent des signes particuliers. La 26 est la « belle maison », la 27 l’« eau », et dans la plupart des reconstitutions un pion tombé dans l’eau recule. Les cases 28 à 30 portaient des nombres ou des dieux de l’au-delà."],"cap":["Un plateau de senet. Les pions avancent en S ; les cinq dernières cases (26–30) portent des signes"]},{"h":"Avancer avec des bâtons","p":["Au lieu de dés, on lançait quatre bâtons plats d’un côté et ronds de l’autre, ou des osselets. Beaucoup de chercheurs pensent qu’on avançait du nombre de faces plates visibles, aucune valant cinq.","C’est exactement le compte des bâtons de yut de la lointaine Corée. Lancez-les dans la salle Hasard du musée et voyez combien certains nombres sortent plus souvent."],"cap":["Bâtons de lancer égyptiens (lancez-les dans la salle Hasard)"]},{"h":"Les boîtes de jeu de Toutânkhamon","p":["La tombe de Toutânkhamon, ouverte par Howard Carter en 1922, renfermait au moins cinq boîtes de jeu. La plus grande, en ébène et ivoire, a un tiroir pour les pions et les bâtons.","Les boîtes à double plateau étaient courantes à l’époque : le senet d’un côté et, de l’autre, le même jeu de vingt cases que le jeu royal d’Ur. Le roi devait pouvoir jouer à l’un comme à l’autre dans l’au-delà."],"cap":["La boîte de senet de Toutânkhamon — à voir en 3D et à jouer dans la salle Collection"]}],"tl":[["v. 3100 av. J.-C.","Fragments d’un plateau de type senet dans une tombe de la Ire dynastie"],["v. 2600 av. J.-C.","Des peintures de l’Ancien Empire montrent des joueurs"],["Dès v. 1550 av. J.-C.","Nouvel Empire : le senet se lie au voyage dans l’au-delà"],["v. 1323 av. J.-C.","Cinq boîtes de jeu dans la tombe de Toutânkhamon"],["v. 1250 av. J.-C.","Néfertari est peinte devant un plateau de senet"],["1922","Carter ouvre la tombe de Toutânkhamon"],["1978","Kendall publie une reconstitution des règles"]]},"lewis":{"title":"Les pièces d’échecs sorties du sable","lead":"Des pièces médiévales trouvées sur une île écossaise en 1831 — et une autre, du même atelier, réapparue dans un tiroir 188 ans plus tard.","s":["En 1831, on trouva sur l’île de Lewis, au nord-ouest de l’Écosse, un ensemble de pièces sculptées surtout dans l’ivoire de morse : 78 pièces d’échecs, 14 pions de jeux de table et une boucle, soit 93 objets.","Le lieu et les circonstances exactes de la découverte restent flous. On cite le plus souvent la baie d’Uig, sur la côte ouest, mais d’autres lieux ont été proposés. On ignore qui les a enfouies là, et pourquoi.","On pense qu’elles ont été sculptées à la fin du XIIe siècle dans la région de Trondheim, en Norvège : rois, reines pensives, évêques, cavaliers sur de petits chevaux trapus et gardes mordant le bord de leur bouclier — sans doute les berserkers des sagas nordiques.","Aujourd’hui, 82 pièces sont au British Museum et 11 au National Museum of Scotland. On dit depuis longtemps qu’il manque quelques pièces pour compléter les jeux.","En 2019, un garde acheté 5 livres seulement en 1964 par un antiquaire d’Édimbourg, et rangé par sa famille dans un tiroir, a été reconnu comme venant de l’atelier des échecs de Lewis. Il a été vendu chez Sotheby’s pour 735 000 livres."],"quiz":[["En quelle année les pièces furent-elles trouvées à Lewis ?","1831","1066","1931","1700"],["En quoi les pièces sont-elles surtout taillées ?","En ivoire de morse","En marbre","En or","En verre"],["En quelle année le garde vendu en 2019 avait-il été acheté 5 livres ?","1964","1831","1990","2018"]],"kf":["93 pièces et disques trouvés sur l’île de Lewis (Écosse) en 1831","Sculptés surtout dans l’ivoire de morse, en Norvège, à la fin du XIIe siècle","Aujourd’hui partagés entre le British Museum et les National Museums Scotland"],"more":[{"h":"Les 78 pièces d’échecs","p":["Les 78 pièces comptent 8 rois, 8 dames, 16 évêques, 15 cavaliers, 12 gardiens et 19 pions — les restes d’au moins quatre jeux.","Les évêques portent la mitre. Le passage de l’« éléphant » à l’évêque (notre fou) s’est fait en Europe, et les pièces de Lewis en sont parmi les premiers exemples. Certains gardiens mordent leur bouclier : on y voit des berserkers, guerriers combattant en transe."],"cap":["Les échecs de Lewis (à voir en 3D dans la salle Collection)","Les 78 pièces par type"]},{"h":"Ivoire de morse et mers du Nord","p":["La plupart sont en ivoire de morse, quelques-unes en dent de baleine. L’ivoire de morse était un trésor des mers du Nord, venu du Groenland et du nord de la Norvège.","Lewis appartenait alors aux îles du roi de Norvège ; elle passa à l’Écosse par le traité de Perth en 1266. Près de la cathédrale de Trondheim, on a trouvé des fragments sculptés de la même manière — un indice sur leur lieu de fabrication."],"cap":[]},{"h":"La légende de la découverte et la célébrité d’aujourd’hui","p":["On raconte bien des versions : une vache qui les aurait déterrées du sable, ou un habitant, Malcolm MacLeod. Le découvreur les vendit vite et, via Édimbourg, le British Museum en acheta la plupart.","Avec leurs mines bougonnes et comiques, elles sont très populaires et leurs répliques se vendent partout. Les échecs version sorcier du film Harry Potter à l’école des sorciers (2001) s’inspiraient des pièces de Lewis."],"cap":[]}],"tl":[["Fin du XIIe siècle","Les pièces sont faites en Norvège (vers Trondheim)"],["1266","Le traité de Perth cède les îles, dont Lewis, à l’Écosse"],["1831","Les 93 pièces sont trouvées ensemble à Lewis"],["1831–32","Le British Museum en achète 82"],["1888","Le musée national écossais en acquiert 11"],["2001","Elles apparaissent dans les échecs version sorcier de Harry Potter"],["2019","Un gardien acheté 5 £ est vendu 735 000 £"]]},"tafl":{"title":"La fuite du roi et une traduction erronée","lead":"Les règles du jeu de plateau des Vikings ont été tirées d’un journal de voyage en Laponie du XVIIIe siècle.","s":["Dans l’Europe du Nord de l’époque viking, on jouait à des jeux de plateau appelés tafl. Un roi au centre et ses quelques défenseurs affrontent une armée plus nombreuse qui les encercle : un jeu entre deux camps inégaux.","Un plateau en bois du Xe siècle trouvé à Ballinderry (Irlande) en 1932 compte 7×7 trous, dont le centre et les quatre coins sont marqués : sans doute la place du roi et ses refuges.","Mais presque aucune description médiévale des règles ne subsiste. Un indice essentiel est le journal du naturaliste Linné, alors âgé de 25 ans, lors de son voyage en Laponie (nord de la Suède) en 1732. Il y nota comment les Samis jouaient à un jeu appelé tablut.","Le journal fut publié en traduction anglaise en 1811, mais la traduction comportait des erreurs. La reconstitution de Murray (1913), fondée sur elle, devint pour longtemps la règle de référence du tafl.","Joueurs et chercheurs ont ensuite corrigé l’erreur, et l’on joue aujourd’hui de nombreuses versions des règles. Le tafl de l’Atlas en est une."],"quiz":[["Quel jeu Linné nota-t-il en Laponie ?","Le tablut","Le senet","Le mancala","Les échecs"],["Quelle pièce les défenseurs cherchent-ils à mener dans un coin ?","Le roi","La reine","Un drapeau","Un navire"],["Quand parut la traduction anglaise fautive ?","1811","1732","1932","1066"]],"kf":["Un roi et quelques défenseurs au centre, encerclés par une armée plus nombreuse : un jeu à deux camps inégaux","Joué dans l’Europe du Nord à l’époque viking, sur des plateaux de 7×7 à 19×19","Les règles nous sont parvenues par le journal de voyage de Linné (1732)… et sa traduction anglaise fautive"],"more":[{"h":"Le plateau de Ballinderry","p":["Découvert dans un habitat lacustre (crannog) du centre de l’Irlande, le plateau de Ballinderry est en if. Ses 49 trous, en grille de 7×7, recevaient sans doute des pions munis d’un tenon.","Une poignée sculptée en forme de tête humaine dépasse du cadre : c’était un plateau qu’on emportait. Les sources irlandaises nomment un tafl de 7×7, le brandubh (« corbeau noir »), qui a pu s’y jouer."],"cap":["Le plateau de Ballinderry (7×7) avec la position de départ du brandubh irlandais. Les anneaux dorés marquent le centre et les quatre coins"]},{"h":"Le tablut de Linné","p":["Le tablut noté par Linné se joue sur 9×9. Le roi occupe le trône central ; ses 8 « Suédois » affrontent 16 « Moscovites ».","Toutes les pièces avancent en ligne droite d’autant de cases qu’elles veulent, comme une tour, et sont capturées lorsque deux ennemies les prennent en tenaille. Les défenseurs gagnent si le roi atteint le bord ; les attaquants, s’ils l’encerclent des quatre côtés. Linné mêlait latin et suédois, et plusieurs points ont changé dans la traduction anglaise."],"cap":["Le tablut tel que Linné l’a noté (9×9) : le roi sur le trône central, 8 défenseurs, 16 attaquants. Les défenseurs gagnent si le roi atteint une case verte du bord"]},{"h":"Des plateaux qui grandissent, un jeu qui s’efface","p":["Outre le 7×7, il existait des plateaux de 9×9, le 11×11 gallois et même du 19×19. Le plus grand, l’Alea Evangelii, est dessiné dans un manuscrit du XIIe siècle qui le dit venu de la cour du roi Æthelstan d’Angleterre, au Xe siècle.","Quand les échecs se répandent en Europe du Nord aux XIIe et XIIIe siècles, le tafl tombe peu à peu dans l’oubli. Seul le tablut survit, dans la lointaine Laponie — et Linné l’a noté par hasard. Aujourd’hui, des tournois internationaux se jouent sur 11×11 et le jeu séduit de nouveaux joueurs."],"cap":["Le trésor de Lewis (XIIe siècle) : avec les pièces d’échecs, 14 disques pour un jeu de plateau"]}],"tl":[["Xe s.","Fabrication du plateau de Ballinderry en Irlande"],["924–939","On jouerait à l’Alea Evangelii à la cour d’Æthelstan"],["XIIe s.","L’Alea Evangelii est dessiné dans un manuscrit"],["XIIe–XIIIe s.","Les échecs gagnent l’Europe du Nord, le tafl disparaît"],["1732","Linné note le tablut en Laponie"],["1811","Parution de Lachesis Lapponica, traduction anglaise de son journal"],["1913","Murray reconstitue le tafl dans A History of Chess"],["1932","Découverte du plateau de Ballinderry"]]},"goose":{"title":"Le jeu de l’oie, un cadeau pour un roi","lead":"Une course de dés sur une spirale de 63 cases fut offerte à un roi, puis jouée dans toute l’Europe.","s":["Le jeu de l’oie est une course : on lance les dés et l’on avance sur une spirale de 63 cases jusqu’au but, au centre. Tomber sur une oie fait avancer encore du même nombre. Le puits, la prison et la mort vous arrêtent ou vous renvoient au départ.","On pense qu’il est né dans l’Italie du XVIe siècle. François Ier de Médicis, grand-duc de Toscane, l’aurait offert au roi Philippe II d’Espagne entre 1574 et 1587.","En Angleterre, l’imprimeur londonien John Wolfe enregistra en 1597 « le nouveau et très plaisant jeu de l’oie ». Aux XVIIe et XVIIIe siècles, il fut immensément populaire dans toute l’Europe.","Imprimé sur papier, il se répandit en d’innombrables versions illustrées : plateaux pour apprendre la géographie, plateaux de contes et de fables, et même publicitaires. On pense qu’il a servi de modèle à bien des jeux de course ultérieurs.","Un plateau à double face du Metropolitan Museum of Art porte le jeu de l’oie d’un côté et les échecs de l’autre. Sans doute fait à la fin du XVIe siècle par des artisans du Gujarat (Inde), il pourrait être le plus ancien plateau de jeu de l’oie conservé."],"quiz":[["Combien de cases compte le jeu de l’oie ?","63","64","100","30"],["Qui aurait offert le jeu au roi d’Espagne ?","François Ier de Médicis","Napoléon","Élisabeth Ire","Louis XIV"],["Que se passe-t-il si l’on tombe sur une oie ?","On avance encore du même nombre","On retourne au départ","On passe un tour","On échange sa place avec un rival"]],"kf":["Une course le long d’une spirale de 63 cases jusqu’au but central, au gré des dés","Né dans l’Italie du XVIe siècle et, dit-on, offert par les Médicis au roi d’Espagne","Diffusé en feuilles imprimées, en d’innombrables versions aux images et thèmes nouveaux"],"more":[{"h":"Une spirale de 63 cases","p":["Dans la version la plus connue, il y a quelques cases spéciales en plus des oies. Le pont du 6 vous porte au 12 ; à l’hôtellerie du 19 on passe un tour ; dans le puits du 31 et la prison du 52, on reste bloqué jusqu’à ce qu’un autre joueur vienne vous délivrer.","Le labyrinthe du 42 renvoie au 30, et la mort du 58 renvoie au départ. Il faut tomber pile sur le 63 : les points en trop font reculer. Le dernier pas est le plus difficile."],"cap":["Les 63 cases disposées en spirale de l’extérieur vers l’intérieur. Vert : les oies ; bleu : le pont ; jaune : les attentes (hôtellerie, puits, prison) ; rouge : les reculs (labyrinthe, mort) ; or : le but"]},{"h":"L’énigme du neuf","p":["Les oies occupent le 5, le 9, le 14, le 18…, à des intervalles alternés de 4 et 5. Chaque multiple de 9 porte une oie : un 9 tombant sur le 9 vous mènerait au 18, au 27… et droit au 63.","D’où la règle spéciale des versions à deux dés : un premier coup de 6 et 3 mène au 26, et de 5 et 4 au 53. Le nombre 63 vaut 7×9 et a été rapproché de l’âge de 63 ans, tenu alors pour l’année la plus périlleuse de la vie."],"cap":["Les oies se suivent tous les 4 et 5 cases : il y a toujours une oie sur les multiples de 9. Un 9 au premier coup sauterait d’oie en oie jusqu’au 63"]},{"h":"L’imprimerie le répand","p":["Les plateaux étaient tirés sur cuivre ou sur bois et devinrent bon marché. En France, c’était le jeu de l’oie ; en Espagne, le juego de la oca, où une comptine « d’oie en oie » reste une expression courante.","Les versions illustrées se multiplièrent : plateaux pour apprendre la géographie et l’histoire, sur la Révolution ou Napoléon, et même réclames pour des produits. Sur la même piste de 63 cases, chaque époque a dessiné ses propres préoccupations."],"cap":[]}],"tl":[["XVIe s.","Naissance supposée en Italie"],["1574–87","François Ier de Médicis l’aurait offert à Philippe II d’Espagne"],["fin XVIe s.","Au Gujarat (Inde), un plateau double face : l’oie d’un côté, les échecs de l’autre"],["1597","John Wolfe l’enregistre pour l’imprimer à Londres"],["XVIIe–XVIIIe s.","Engouement dans toute l’Europe, versions à thème de plus en plus nombreuses"],["années 1790","Plateaux consacrés à la Révolution française"],["XIXe s.","Imprimé en masse dans de nombreux pays comme jeu d’enfants"]]},"shogi":{"title":"Quand sont nés les parachutages du shogi ?","lead":"Dans toute la famille des échecs, seul le shogi permet de remettre en jeu, pour son camp, les pièces capturées. Quand — et pourquoi — cette règle est-elle apparue ?","s":["L’ancêtre indien des échecs s’est répandu vers l’est et l’ouest ; au Japon, il est devenu le shogi. Les plus anciennes pièces de shogi du Japon sont 16 pièces trouvées au début des années 1990 dans l’ancienne enceinte du Kōfuku-ji, à Nara. Une étiquette datée de 1058 (Tenki 6) était avec elles : on pense donc que les pièces datent de la même époque.","Les écrits de l’époque le mentionnent aussi. Le Shin Sarugaku-ki, du milieu du XIe siècle, le nomme, et le Nichūreki, qui rassemble des documents de la fin de l’époque de Heian, décrit un « shogi de Heian » avec rois, généraux d’or et d’argent, cavaliers, lanciers et pions.","Aux époques de Kamakura et de Muromachi apparurent de nombreuses formes plus grandes, avec plus de pièces. Le « petit shogi », à l’origine du jeu actuel, ajouta la tour et le fou… et une pièce aujourd’hui disparue : l’éléphant ivre.","La règle du parachutage serait apparue vers le XVIe siècle. Selon la tradition, l’empereur Go-Nara fit retirer l’éléphant ivre du petit shogi, et les parachutages auraient commencé vers la même époque.","On ignore pourquoi. Une explication : les pièces des deux camps sont de la même couleur, distinguées seulement par leur orientation, si bien qu’une pièce capturée se réutilise facilement. Grâce à cela, l’échiquier ne se vide pas et les parties nulles sont rares."],"quiz":[["Quelle date portait l’étiquette trouvée avec les pièces du Kōfuku-ji ?","1058 (Tenki 6)","701 (Taihō 1)","1582 (Tenshō 10)","1868 (Meiji 1)"],["Quand la règle du parachutage serait-elle apparue ?","Vers le XVIe siècle","Vers le VIIIe siècle","Vers le XIXe siècle","Au XXe siècle"],["Quelle raison avance-t-on pour la facilité de réutiliser les pièces ?","Les pièces des deux camps ont la même couleur, distinguées par l’orientation","Les pièces étaient en or","Le plateau avait peu de cases","On choisissait les pièces aux dés"]],"kf":["Un cousin des échecs né en Inde et devenu japonais, joué sur un plateau de 9×9","Les plus anciennes pièces viennent de l’ancien enclos du Kōfuku-ji, trouvées avec une étiquette datée de 1058","Les « pièces en main » — rejouer pour soi les pièces capturées — seraient apparues vers le XVIe siècle"],"more":[{"h":"Une seule couleur, la direction fait la différence","p":["Les pièces d’échecs sont peintes en blanc et en noir, mais celles du shogi ont toutes la couleur du bois : on sait à qui elles appartiennent selon le sens de la pointe de la pièce à cinq côtés. C’est cette forme qui permet de retourner une pièce capturée et de la parachuter sur le plateau.","Chaque pièce porte son nom, et en entrant dans le camp adverse elle peut se retourner et « se promouvoir ». Le pion devient le と de son revers et se déplace comme un général d’or. Des jetons plats et inscrits plutôt que des figurines sculptées : un trait que le shogi partage avec ses cousins d’Asie orientale, le xiangqi chinois et le janggi coréen."],"cap":["Les pièces de shogi ont la même couleur dans les deux camps ; on les distingue par le sens de leur pointe. À droite : un pion retourné, « promu » (tokin)"]},{"h":"L’âge des shogi géants","p":["Des époques de Kamakura et de Muromachi jusqu’à celle d’Edo, on inventa des shogi de plus en plus grands, aux pièces toujours plus variées. Le chū shogi de 12×12 fut très joué durant toute l’époque d’Edo et a encore ses amateurs.","Les textes vont plus loin encore : le dai shogi de 15×15, le tai shogi de 25×25 et le taikyoku shogi, avec 804 pièces sur 36×36 cases. Mais le jeu de tous les jours était le shō shogi de 9×9, qui gagna les pièces en main et devint le shogi d’aujourd’hui."],"cap":["Tailles de plateau comparées depuis un même coin : 9×9 pour le shogi actuel (40 pièces), 12×12 pour le chū shogi (92), 15×15 pour le dai shogi (130), 25×25 pour le tai shogi (354), 36×36 pour le taikyoku shogi (804)"]},{"h":"Le shogi à Edo","p":["À l’époque d’Edo apparurent des maisons de shogi pensionnées par le shogunat ; Ōhashi Sōkei passe pour le premier maître. Chaque année, les meilleurs jouaient devant le shōgun lors des « parties du château », fixées ensuite au 17 novembre — d’où l’actuelle Journée du shogi.","Le shogi était aussi un plaisir populaire : l’estampe de Harunobu montre un jeune couple jouant près d’une moustiquaire. On vit aussi paraître des recueils de problèmes de tsume-shogi dignes d’œuvres d’art, comme le Shōgi Zukō d’Itō Kanju (1755)."],"cap":["Estampe en couleurs de Suzuki Harunobu (vers 1767–69) : une jeune femme et un jeune homme jouent au shogi près d’une moustiquaire"]}],"tl":[["1058","Pièces de l’ancien enclos du Kōfuku-ji (trouvées avec une étiquette de l’an Tengi 6)"],["milieu XIe s.","Le Shinsarugakuki cite le shogi"],["début de Kamakura","Le Nichūreki énumère les pièces du shogi de Heian"],["vers le XVIe s.","Naissance supposée des pièces en main"],["1612","Ōhashi Sōkei et d’autres reçoivent, dit-on, une pension du shogunat"],["1716","Les parties du château sont fixées au 17 novembre"],["1755","Shōgi Zukō d’Itō Kanju"],["1975","Le 17 novembre devient la Journée du shogi"]]},"pachisi":{"title":"Comment le pachisi est devenu le ludo","lead":"Un jeu de plateau en croix des cours indiennes a changé de nom et gagné les salles de jeux du monde entier.","s":["L’Inde connaît le chaupar et le pachisi : quatre joueurs font avancer des pions autour d’un plateau en forme de croix. Le chaupar se joue avec de longs dés (pasa), le pachisi avec des cauris lancés. Le nom pachisi signifie « vingt-cinq », le plus haut score que donnaient les cauris.","Même les dieux y jouaient. Une peinture de la fin du XVIIe siècle montre le dieu Shiva et son épouse Parvati autour d’un plateau de chaupar, sur une peau de tigre.","À Fatehpur Sikri, la cité de l’empereur moghol Akbar (XVIe siècle), une cour conserve dans son dallage un immense plateau en croix. Akbar y aurait joué avec des personnes vêtues de couleurs en guise de pions.","Au XIXe siècle, le jeu traversa les mers. Aux États-Unis, il fut vendu sous le nom de Parcheesi, marque déposée en 1874. En Grande-Bretagne, il fut vendu dans les années 1890 sous le nom de Ludo — « je joue » en latin — et devint un classique familial.","Le ludo est plus simple : un seul dé, et un 6 pour sortir un pion. Il a des cousins sous d’autres noms partout dans le monde, comme les Petits Chevaux en France ou le Mensch ärgere Dich nicht (« Ne t’énerve pas ») en Allemagne."],"quiz":[["Que signifie le nom « pachisi » ?","Vingt-cinq","La route du roi","Croix","Cauri"],["Quelle cité d’Akbar conserve une cour au plateau géant ?","Fatehpur Sikri","Le Qutb Minar de Delhi","Le Taj Mahal","Ellora"],["Que signifie « ludo » en latin ?","Je joue","Je gagne","Je cours","Je lance"]],"kf":["Un jeu de course sur un plateau indien en croix : quatre joueurs, en deux équipes, font faire le tour à leurs pions","Le nom signifie « 25 », le plus fort coup des cauris","Au XIXe siècle, il a voyagé et s’est répandu dans le monde sous les noms de Parcheesi, ludo et d’autres"],"more":[{"h":"La croix et le chemin","p":["Le plateau du pachisi est une croix dont les quatre bras partent du charkoni central. Chaque bras compte 3 × 8 cases, soit 96 en tout. Les plateaux étaient souvent brodés sur tissu : on pouvait les rouler et les ranger.","Les pions quittent le centre, descendent la colonne du milieu de leur bras, font une fois le tour du plateau dans le sens inverse des aiguilles d’une montre et remontent la colonne du milieu jusqu’au centre. Les joueurs assis face à face sont partenaires ; une équipe gagne quand tous deux ont ramené leurs quatre pions."],"cap":["Un plateau en croix (chaque bras de 3 × 8 cases). La ligne bleue est le chemin d’un joueur : descendre au milieu de son bras, faire tout le tour dans le sens inverse des aiguilles d’une montre, puis remonter au centre"]},{"h":"Compter les cauris","p":["Au pachisi, on lance six coquillages cauris : le nombre tombé ouverture en haut fixe le déplacement. De deux à six, on avance d’autant ; mais avec un seul, on avance de 10, et avec aucun, de 25.","À 1 chance sur 64, le 25 est le coup le plus rare et le plus fort — il a donné son nom au jeu. Un 6, un 10 ou un 25 donnent droit à un nouveau lancer. Le chaupar, lui, se joue avec trois longs dés en bâtonnet marqués 1, 2, 5 et 6."],"cap":["Sur six cauris, combien tombent ouverture en haut (rangée du haut) et de combien on avance (rangée du bas). La hauteur des barres montre la fréquence si chaque coquillage tombe d’un côté ou de l’autre à égalité"]},{"h":"Nouveaux noms, nouveaux pays","p":["Par l’intermédiaire des Britanniques en Inde, le jeu gagna l’Europe et l’Amérique au XIXe siècle. Aux États-Unis, il devint la marque Parcheesi ; en Grande-Bretagne, le ludo fut breveté en 1896, avec des règles simplifiées et un seul dé cubique à la place des cauris.","L’Allemagne eut en 1914 le Mensch ärgere dich nicht (« Ne t’énerve pas »), et l’Espagne joue au parchís ; en France, on connaît les petits chevaux. Noms et détails changent d’un pays à l’autre, mais l’ossature reste : faire le tour de la croix et rentrer à la maison."],"cap":[]}],"tl":[["XVIe s.","Une cour à croix géante est tracée à Fatehpur Sikri, la ville d’Akbar"],["XVIIe–XVIIIe s.","Les miniatures indiennes montrent souvent des joueurs autour du chaupar"],["1694–95","Devidasa peint Shiva et Parvati jouant au chaupar"],["1874","Parcheesi devient une marque aux États-Unis"],["1896","Le ludo est breveté en Grande-Bretagne"],["1914","Le Mensch ärgere dich nicht est mis en vente en Allemagne"]]},"go":{"title":"Ce que raconte un goban vieux de 1 300 ans","lead":"Le goban du Shōsōin a 19 lignes comme aujourd’hui — et 17 marques en forme de fleur, à la différence d’aujourd’hui.","s":["Le go est né dans la Chine ancienne. La légende veut que le sage roi Yao l’ait créé pour instruire son fils. Le livre de Mencius, antérieur à notre ère, cite un maître du jeu, Yi Qiu.","On pense que la taille du plateau a changé au fil du temps : des plateaux de 17 lignes furent aussi utilisés anciennement, et le plateau actuel de 19 lignes s’est imposé plus tard.","On ignore quand le go arriva au Japon, mais on y jouait à l’époque de Nara. Les règles pour les moines et les nonnes interdisaient la musique et les jeux d’argent, mais permettaient le go et le koto — un traitement bien différent de celui du sugoroku.","Le goban en marqueterie du Shōsōin s’est transmis comme un trésor lié à l’empereur Shōmu. Il a 19 lignes comme aujourd’hui, mais 17 marques en fleur là où le goban actuel a 9 points étoile. Ses deux tiroirs sont liés : en tirer un fait sortir l’autre. Le Shōsōin garde aussi des pierres de go en ivoire teint en rouge et bleu sombre, gravées d’oiseaux.","À l’époque de Heian, le Dit du Genji montre des parties de go. À l’époque d’Edo, des maisons comme les Hon’inbō servirent le shogunat, et le go devint un art où des joueurs professionnels mesuraient leur talent."],"quiz":[["Combien de lignes compte le goban du Shōsōin ?","19","17","13","9"],["Que permettaient les règles aux moines et aux nonnes ?","Le go et le koto","Le sugoroku","Les jeux d’argent","Le kemari"],["Combien de marques en fleur le goban du Shōsōin a-t-il au lieu des points étoile ?","17","9","4","25"]],"kf":["Des pierres noires et blanches posées aux intersections des lignes, pour encercler le plus grand territoire : un jeu né dans la Chine antique","Après une époque de goban à 17 lignes vinrent les 19 lignes ; le Shōsōin conserve un goban de 19 lignes du VIIIe siècle","À Edo, des maisons de go servaient le shogunat ; au XXIe siècle, une IA a battu le meilleur joueur du monde"],"more":[{"h":"Encercler pour capturer, enclore pour gagner","p":["Au go, Noir et Blanc posent à tour de rôle des pierres sur les intersections des lignes. Une pierre posée ne bouge plus. Quand tous les points libres voisins d’une pierre (ou d’un groupe) sont occupés par l’adversaire, elle est capturée et retirée du plateau.","À la fin, le territoire enclos plus les pierres capturées désignent le vainqueur. Les règles sont peu nombreuses, mais le plateau est vaste : on a calculé qu’un goban de 19 lignes admet environ 10 puissance 170 positions possibles."],"cap":["La capture. À gauche : la pierre noire a quatre points libres autour d’elle (en rouge). Au centre : Blanc l’entoure sur trois côtés, il en reste un. À droite : le dernier est bouché, la pierre noire est prise"]},{"h":"De 17 lignes à 19","p":["Un goban en pierre de 17 lignes a été découvert dans une tombe des Han orientaux à Wangdu (Hebei, Chine). Le Classique du go de Dunhuang, daté vers le VIe siècle, décrit 361 intersections : un goban de 19 lignes. Le plateau semble avoir grandi entre-temps.","Le goban du Shōsōin compte 19 lignes, mais au lieu des neuf hoshi actuels il porte des fleurs à 17 endroits. Passer de 289 à 361 intersections a rendu le jeu bien plus profond."],"cap":["Les goban de 17 et de 19 lignes comparés par nombre d’intersections. Les neuf points noirs du goban actuel sont les « hoshi » (points étoiles)"]},{"h":"Le go des immortels, le go des maîtres","p":["Un conte chinois parle d’un bûcheron qui s’arrêta dans la montagne pour regarder des immortels jouer au go — et s’aperçut que tant d’années avaient passé que le manche de sa hache avait pourri. Le go, passe-temps des immortels, ornait volontiers plats et peintures.","À l’époque d’Edo, des maisons de go comme les Hon’inbō étaient pensionnées par le shogunat, et le go fut poli comme un art. La partie d’adieu de Hon’inbō Shūsai, en 1938, devint le roman de Kawabata Yasunari Le Maître ou le tournoi de go. En 2016, l’IA AlphaGo battit le meilleur joueur du monde, Lee Sedol, par quatre victoires à une, à la stupeur générale."],"cap":["Plat en laque sculptée montrant des immortels jouant au go (dynastie Ming, ère Xuande, 1425–36)"]}],"tl":[["vers le IVe s. av. J.-C.","Mencius nomme le maître de go Yi Qiu"],["Han orientaux","Un goban de pierre de 17 lignes est déposé dans une tombe de Wangdu"],["vers le VIe s.","Le Classique du go de Dunhuang décrit 19 lignes et 361 intersections"],["VIIIe s.","Le goban en santal marqueté du Shōsōin"],["1612","Hon’inbō Sansa et d’autres reçoivent, dit-on, une pension du shogunat"],["1938","Partie d’adieu de Hon’inbō Shūsai, futur roman de Kawabata"],["2016","AlphaGo bat Lee Sedol quatre à un"]]},"draughts":{"title":"Comment sont nées les dames","lead":"Un jeu de plateau arabe, l’échiquier et la reine des échecs : les dames seraient nées de la rencontre des trois.","s":["On considère comme ancêtre des dames l’alquerque, joué sur une grille de 5×5 points reliés par des lignes. En arabe, il s’appelait qirq et il est cité dans le Livre des chansons du Xe siècle. Les Maures l’apportèrent en Espagne, et ses règles figurent dans le Livre des jeux commandé par Alphonse X de Castille au XIIIe siècle.","Vers le XIIe siècle, sans doute dans le sud de la France, on se mit à déplacer les pions de l’alquerque sur un échiquier. Ce fut le jeu de fierges. Les pions prirent le nom de la reine des échecs de l’époque, la fierge (fers).","La promotion — un pion qui atteint le fond devient plus fort — est déjà mentionnée dans une chronique du milieu du XIIIe siècle. Elle a peut-être été empruntée au pion des échecs devenant reine.","Le grand changement eut lieu en France vers 1535 : on ajouta la prise obligatoire — si l’on peut prendre, on doit prendre — et le jeu fut appelé « jeu forcé ». Le draughts anglais et le checkers américain en descendent.","L’ancien jeu sans prise obligatoire survécut comme « jeu plaisant de dames » et mena plus tard au jeu international sur 10×10. D’un même ancêtre naquirent bien des « jeux de dames », de reines."],"quiz":[["Quel jeu est considéré comme l’ancêtre des dames ?","L’alquerque","Le senet","Le liubo","Le mancala"],["Quand et où la prise obligatoire fut-elle ajoutée ?","En France, vers 1535","À Bagdad, au Xe siècle","Aux États-Unis, en 1900","Au Japon, au VIIIe siècle"],["Les pions du jeu de fierges portaient le nom de quoi ?","De la reine des échecs (fers)","Du roi des échecs","Des dés","Du cavalier"]],"kf":["Né quand les pions du jeu arabe de l’alquerque passèrent sur un échiquier","Les pions avancent en diagonale et prennent en sautant ; arrivés au fond, ils vont à dame","La prise obligatoire apparut vers 1535, et le jeu (sur 8 × 8) a été résolu en 2007"],"more":[{"h":"Des points et des lignes à l’échiquier","p":["Le plateau d’alquerque compte 25 points en grille de 5 × 5, reliés par des lignes. Chaque camp place 12 pions, et la partie commence à partir du seul point vide, au centre. Les pions suivent les lignes et prennent en sautant par-dessus un pion adverse voisin.","Quand les pions passèrent sur un échiquier, on n’utilisa plus que les cases d’une couleur. Un damier de 8 × 8 a 32 cases sombres ; en remplissant les trois premières rangées de chaque côté, on obtient 12 pions par camp — comme à l’alquerque."],"cap":["Le plateau d’alquerque et sa position de départ : 5 × 5 points reliés par des lignes droites et diagonales, 12 pions par camp, seul le centre vide"]},{"h":"Sauter pour prendre, aller à dame","p":["Les pions avancent d’une case en diagonale et prennent en sautant un pion adverse voisin si la case suivante est libre. Si une autre prise est alors possible, ils continuent de sauter. Aujourd’hui, si l’on peut prendre, on doit prendre.","Le pion qui atteint la dernière rangée va à dame — on pose un second pion dessus — et peut alors reculer. Aux dames internationales sur 10 × 10, la dame parcourt toute une diagonale, ce qui change tout dans les finales."],"cap":["Prise et promotion aux dames anglaises. Le pion rouge saute deux pions blancs d’affilée (×), puis atteint la dernière rangée et devient dame : deux pions empilés"]},{"h":"Un jeu résolu, une famille qui s’étend","p":["Au Canada, Jonathan Schaeffer et son équipe créèrent le programme Chinook pour les dames anglaises. En 1992, il affronta Marion Tinsley, qui n’avait presque pas perdu en plus de 40 ans, et Tinsley l’emporta. L’équipe poursuivit ses calculs et prouva en 2007 qu’avec un jeu parfait des deux côtés, la partie est nulle.","Pendant ce temps, la famille issue du même ancêtre vit partout : dames internationales sur 10 × 10, chachki russes, dama turque aux déplacements orthogonaux, dames canadiennes sur 12 × 12… avec des tournois dans chaque pays."],"cap":[]}],"tl":[["Xe s.","Le Livre des chansons nomme le qirq (alquerque)"],["vers le XIIe s.","Naissance du fierges, sans doute dans le sud de la France"],["1283","Le Livre des jeux d’Alphonse X décrit l’alquerque"],["vers 1535","La prise obligatoire apparaît en France"],["1547","Torquemada publie en Espagne le premier livre sur les dames"],["XVIIIe s.","Le damier de 10 × 10 se répand en France et aux Pays-Bas"],["1992","Tinsley bat le programme Chinook"],["2007","Preuve que les dames anglaises sont nulles avec un jeu parfait"]]},"reversi":{"title":"Reversi et Othello : qui les a inventés ?","lead":"Un jeu où l’on encadre et retourne des pions noirs et blancs — et deux hommes de l’Angleterre du XIXe siècle qui se le disputèrent.","s":["Dans le Londres des années 1880, deux Anglais, Lewis Waterman et John W. Mollett, affirmaient chacun être l’inventeur du jeu et traitaient l’autre d’imposteur.","Le jeu de Mollett, Annexation, se jouait sur un plateau en croix. Le Reversi de Waterman utilisait un plateau ordinaire de 8×8, et c’est sa forme qui nous est parvenue. La querelle sur le nom alla même jusqu’au tribunal.","Le reversi se répandit en Europe ; en 1893, la maison allemande Ravensburger en fit l’un de ses premiers produits. Au Japon, il fut décrit dans des livres de l’ère Meiji et appelé aussi genpei-go.","Sa vogue ne dura pas. En 1971, Goro Hasegawa lança « Othello », en fixant l’ouverture avec les quatre premiers pions croisés au centre, et ce fut un engouement au Japon.","Le nom viendrait de la pièce de Shakespeare : le général noir Othello et son épouse blanche Desdémone font écho aux pions noirs et blancs. Les règles des tournois actuels sont celles d’Othello."],"quiz":[["Quand et où vivaient les deux hommes qui se disputèrent le reversi ?","Angleterre, XIXe siècle","France, XVIIIe siècle","Japon, XXe siècle","Italie, XVIe siècle"],["Quelle forme avait le plateau de l’Annexation de Mollett ?","Une croix","Un cercle","Un triangle","Un carré de 8×8"],["Qui lança Othello en 1971 ?","Goro Hasegawa","Hon’inbō Shūsaku","Lewis Waterman","Ravensburger"]],"kf":["Encadrer les pions adverses entre les siens pour les retourner ; à la fin, le plus grand nombre l’emporte","Dans le Londres des années 1880, deux Anglais se disputèrent son invention","Devenu un engouement au Japon dans les années 1970 sous le nom d’Othello, il s’est révélé nul en jeu parfait en 2023"],"more":[{"h":"Encadrer et retourner","p":["On ne peut poser un pion que là où il encadre une ligne de pions adverses entre lui et un pion à soi. Les lignes vont dans huit directions — horizontales, verticales et diagonales — et un coup peut en encadrer plusieurs à la fois. Tous les pions encadrés sont retournés à sa couleur.","Sans coup possible, on passe ; la partie s’arrête quand aucun des deux ne peut jouer. Les pions des coins ne peuvent jamais être encadrés : prendre un coin est un gros avantage. Les forts joueurs comptent moins les pions du moment que les cases laissées à l’adversaire."],"cap":["Le retournement. Un pion noir posé sur la case cerclée de rouge encadre des blancs dans trois directions — horizontale, verticale et diagonale — et les sept pions bordés d’or deviennent noirs"]},{"h":"Les quatre premiers pions","p":["Dans le reversi ancien, les deux joueurs posaient tour à tour les quatre premiers pions sur les quatre cases centrales : le début pouvait donc être côte à côte ou croisé.","L’Othello a fixé le départ croisé. Dès le premier coup, les deux couleurs sont faciles à encadrer et la lutte commence aussitôt. Les championnats du monde partent aujourd’hui de cette position."],"cap":["Les quatre premiers pions. À gauche : un début possible du reversi ancien, mêmes couleurs côte à côte. À droite : le départ croisé fixé par l’Othello"]},{"h":"Humains et ordinateurs","p":["L’Othello est passé du Japon au monde entier, et le premier championnat du monde s’est tenu à Tokyo en 1977. Les règles sont simples : c’est la profondeur du calcul qui fait la différence, et les meilleurs voient des dizaines de coups à l’avance.","En 1997, le programme Logistello affronta le champion du monde Takeshi Murakami en six parties et les gagna toutes. En 2023, le calcul a montré que l’Othello 8 × 8 est nul si les deux camps jouent parfaitement."],"cap":[]}],"tl":[["années 1880","Waterman et Mollett se disputent l’invention à Londres"],["1893","Ravensburger lance le Reversi en Allemagne"],["ère Meiji","Des livres japonais le présentent sous le nom de genpei-go"],["1973","Les boîtes d’Othello sont mises en vente au Japon"],["1977","Premier championnat du monde d’Othello, à Tokyo"],["1997","Logistello bat le champion Takeshi Murakami 6–0"],["2023","L’Othello 8 × 8 est montré nul en jeu parfait"]]},"mancala":{"title":"Où est né le mancala ?","lead":"Un jeu où l’on sème des graines de trou en trou, joué en Afrique et en Asie sous des centaines de noms.","s":["Le mancala est le nom d’une famille de jeux où l’on prend des pierres ou des graines dans un trou pour les semer une à une dans les suivants. Le mot viendrait de l’arabe naqala, « déplacer ».","Noms et règles varient d’un lieu à l’autre — awalé (oware) en Afrique de l’Ouest, bao en Afrique de l’Est, mangala en Turquie, congkak en Asie du Sud-Est, et des centaines d’autres —, sur deux rangées ou quatre, avec un nombre de trous variable.","On le dit souvent très ancien, mais les preuves sûres sont plus récentes qu’on ne croit. Les plus anciens plateaux datés avec certitude sont, à ce jour, des plateaux en céramique et en pierre des VIe–VIIe siècles environ, trouvés sur des sites de l’ancien royaume d’Aksoum, à Matara et Yeha (Érythrée et Éthiopie).","Des exemples plus anciens ont été avancés, mais rien ne dit que ces rangées de trous servaient au mancala, et les chercheurs sont partagés. Selon une hypothèse forte, le jeu s’est répandu d’Aksoum vers l’Arabie et l’intérieur de l’Afrique.","Les descriptions complètes de la manière d’y jouer n’apparaissent que vers le XVIIe siècle. Dans l’Atlas, on peut jouer au mancala selon huit règles, dont l’awalé et la mangala."],"quiz":[["Que signifie le mot arabe à l’origine de « mancala » ?","Déplacer","Graine","Trou","Roi"],["Où a-t-on trouvé les plus anciens plateaux de mancala datés avec certitude ?","Sur des sites de l’ancien royaume d’Aksoum (Éthiopie et Érythrée)","Au Colisée de Rome","Sur la Grande Muraille de Chine","À Stonehenge"],["Quel mancala joue-t-on en Afrique de l’Ouest ?","L’awalé (oware)","Le liubo","Le tafl","Le pachisi"]],"kf":["Une famille de jeux de « semailles » : on prend les graines d’un trou et on les dépose une à une dans les suivants","Les plus anciens tabliers bien datés viennent de l’ancien royaume d’Aksoum, vers les VIe–VIIe siècles","Deux rangées ou quatre, avec ou sans greniers : tablier et règles changent d’une région à l’autre"],"more":[{"h":"Semer","p":["Au mancala, on choisit un trou de son côté, on en sort toutes les graines et on les dépose une à une dans les trous suivants. Ce geste, comme semer dans un champ, s’appelle les semailles.","L’awalé (oware), d’Afrique de l’Ouest, commence avec 48 graines, quatre dans chacun des 12 trous. Si la dernière graine laisse deux ou trois graines dans un trou adverse, on les prend. Savoir où finira une semaille — compter d’avance — est essentiel. L’awalé a traversé l’Atlantique et se joue aussi aux Antilles."],"cap":["Les semailles à l’awalé (oware). Les trois graines du trou cerclé d’or partent une à une dans le sens inverse des aiguilles d’une montre ; la dernière laisse exactement 3 graines dans un trou adverse, qui sont prises (cercle rouge)"]},{"h":"Deux rangées et quatre","p":["Les tabliers de mancala se rangent en gros en deux familles : à deux et à quatre rangées. Les premiers dominent en Afrique de l’Ouest et en Asie ; les seconds s’étendent de l’Afrique de l’Est au sud du continent. Le bao de Tanzanie compte 4 rangées de 8 trous ; son nom veut simplement dire « tablier » en swahili.","Certains, comme le congkak et le sungka d’Asie du Sud-Est, ont à chaque bout un grand trou — un grenier — pour les graines prises. Le kalah, né aux États-Unis au XXe siècle, est un jeu à deux rangées avec greniers ; en 2000, le calcul a montré que le kalah à six trous et quatre graines est gagné par le premier joueur."],"cap":["Exemples de tabliers de mancala : 2 rangées de 6 (awalé et autres), 2 rangées de 7 avec un grenier à chaque bout (congkak d’Asie du Sud-Est et autres), 4 rangées de 8 (bao d’Afrique de l’Est et autres)"]},{"h":"Ceux qui l’ont décrit","p":["On considère souvent l’Anglais Thomas Hyde comme le premier savant européen à décrire le mancala en détail. Dans De Ludis Orientalibus (1694), il en donna le nom arabe et la manière de jouer.","En 1836, Edward W. Lane, décrivant la vie quotidienne au Caire, nota le « mankalah » joué dans les cafés. Aujourd’hui, les chercheurs ont recueilli des jeux du monde entier, et les règles relevées se comptent par centaines."],"cap":[]}],"tl":[["VIe–VIIe s.","Les plus anciens tabliers bien datés, sur des sites d’Aksoum"],["1694","Thomas Hyde décrit le mancala dans De Ludis Orientalibus"],["XVIIIe–XIXe s.","L’awalé et d’autres traversent l’Atlantique jusqu’aux Antilles"],["1836","E. W. Lane note le mankalah du Caire"],["milieu du XXe s.","Le kalah, à deux rangées et greniers, est commercialisé aux États-Unis"],["2000","Calcul : le kalah à six trous et quatre graines est gagné par le premier joueur"]]},"morris":{"title":"Le jeu du moulin est partout","lead":"Un toit de temple, un navire viking, un banc de pierre de cathédrale : ses lignes ont été gravées partout où l’on s’asseyait ensemble.","s":["Au jeu du moulin (nine men’s morris), chacun pose neuf pions sur les 24 points de trois carrés emboîtés ; trois alignés, un « moulin », prennent un pion adverse. Le nom anglais « morris » n’a rien à voir avec la danse : il viendrait du latin merellus, jeton.","Un plateau gravé sur une dalle du toit du temple de Gournah, en Égypte, est souvent présenté comme le plus ancien, vers 1400 av. J.-C. Mais le chercheur Friedrich Berger a relevé des croix coptes parmi ces mêmes gravures et conclu qu’on ne peut pas les dater. Les exemples sûrs commencent à l’époque romaine.","Sur le navire de Gokstad, en Norvège, vers l’an 900, un plateau est gravé sur une planche du pont. En Angleterre, il en reste sur les bancs de pierre des cloîtres de cathédrales comme Canterbury et Salisbury.","Le Livre des jeux d’Alphonse X, de 1283, le montre même joué avec des dés. Shakespeare, dans Le Songe d’une nuit d’été, raconte que les pluies ont rempli de boue le « nine men’s morris » : un plateau creusé dans le pré du village.","En 1996, l’Allemand Ralph Gasser a fait examiner toutes les positions par ordinateur et prouvé qu’avec un jeu parfait des deux côtés la partie est nulle. Entre deux personnes, il reste un très bon jeu."],"quiz":[["D’où viendrait le nom « morris » ?","Du latin « jeton »","D’une danse anglaise","D’un nom de personne","D’un nom de navire"],["Qu’ont relevé les chercheurs sur les plateaux de Gournah ?","Qu’on ne peut pas les dater","Qu’ils sont en or","Qu’ils viennent de Chine","Qu’ils étaient à un empereur"],["Qu’a prouvé un ordinateur en 1996 ?","Avec un jeu parfait, c’est nul","Le premier gagne toujours","Le second gagne toujours","Huit pions suffisent"]],"kf":["Neuf pions chacun sur les 24 points de trois carrés emboîtés ; trois alignés prennent un pion adverse","Depuis l’époque romaine, son tablier a été gravé partout où l’on se réunissait : ponts de navires, bancs de cathédrales","En 1996, toutes les positions ont été examinées par ordinateur : en jeu parfait, c’est nul"],"more":[{"h":"Poser, déplacer, voler","p":["La partie se joue en trois phases. D’abord, les joueurs posent tour à tour leurs neuf pions sur des points libres. Une fois tous posés, ils déplacent un pion à la fois le long d’une ligne vers un point voisin libre.","Trois pions alignés sur une ligne forment un « moulin » et permettent de retirer un pion adverse. Une règle courante permet au joueur réduit à trois pions de « voler » vers n’importe quel point libre. On perd quand il ne reste que deux pions ou qu’on ne peut plus bouger."],"cap":["Un tablier de jeu du moulin. Les Blancs ont formé un moulin sur le côté extérieur (or) et peuvent prendre un pion noir (croix rouge)"]},{"h":"De trois pions à douze","p":["La famille se nomme d’après le nombre de pions. Le moulin à trois, avec trois pions chacun, est un petit tablier proche du morpion. Le moulin à six utilise deux carrés emboîtés.","Le moulin à douze ajoute des diagonales au tablier du moulin à neuf. En Afrique du Sud, on l’appelle morabaraba ; les jeunes bouviers, dit-on, le traçaient sur le sol, et il a aujourd’hui ses tournois."],"cap":["Tabliers comparés. Le nombre indique les pions de chaque joueur : moulin à trois, à six, à neuf et à douze"]},{"h":"Un champion d’échecs et un ordinateur","p":["Le champion du monde d’échecs Emanuel Lasker se passionna lui aussi pour ce jeu. Dans Brettspiele der Völker (1931), il proposa une version à dix pions chacun, où l’on peut déplacer avant d’avoir tout posé.","En 1996, le Suisse Ralph Gasser combina des tables complètes de finales et une recherche depuis l’ouverture pour montrer que le jeu du moulin est nul si les deux camps jouent parfaitement. Le tablier n’a que 24 points, mais les positions se comptent par milliards."],"cap":[]}],"tl":[["époque romaine","Des tabliers gravés dans la pierre à travers l’empire (premiers exemples sûrs)"],["vers 900","Un tablier est gravé sur une planche du pont du navire de Gokstad (Norvège)"],["1283","Le Livre des jeux d’Alphonse X illustre le moulin"],["Moyen Âge","Des tabliers gravés sur les bancs des cloîtres de cathédrales anglaises"],["années 1590","Le Songe d’une nuit d’été de Shakespeare évoque un tablier rempli de boue"],["1931","Lasker propose une nouvelle version dans Brettspiele der Völker"],["1996","Gasser prouve qu’en jeu parfait, c’est nul"]]},"patolli":{"title":"Le patolli, la course de haricots aztèque","lead":"Un plateau en croix et des haricots en guise de dés : un jeu aux paris si fiévreux que les Espagnols l’ont interdit.","s":["Le patolli était un jeu de course des Aztèques du Mexique. Son nom signifie haricots : on lançait cinq haricots rouges marqués ou percés sur une face et l’on avançait selon les marques visibles, sur un parcours en croix peint sur une natte ou au sol.","Diego Durán, qui a décrit la région au XVIe siècle, écrit que les joueurs brûlaient de l’encens et priaient les haricots avant de lancer, et invoquaient Macuilxochitl, dieu des jeux, pour gagner.","Les nobles misaient bijoux, manteaux, voire eux-mêmes ; certains perdants devenaient esclaves. On raconte aussi que l’empereur Moctezuma regardait jouer ses nobles.","Les frères espagnols, hostiles aux paris et aux prières aux anciens dieux, ont interdit le patolli, brisé les nattes et brûlé les haricots : peu de jeux ont survécu. Pourtant, des plateaux gravés dans des sols de pierre et des rochers ont été trouvés à Teotihuacan et sur des sites mayas, et en 1977 parmi des pétroglyphes du Jalisco.","Un plateau en croix que les pions parcourent ressemble beaucoup au pachisi indien. En 1878, l’Anglais E. B. Tylor a défendu une origine asiatique ; aujourd’hui, on pense le plus souvent qu’ils sont nés séparément."],"quiz":[["Que lançait-on au patolli à la place des dés ?","Des haricots marqués","Des os d’animaux","Des coquillages","Des bâtons"],["Selon les sources, pourquoi le patolli fut-il interdit ?","Les paris et les prières aux anciens dieux","Le plateau était trop grand","Les haricots coûtaient cher","Le roi avait perdu"],["À quel jeu le plateau du patolli ressemble-t-il beaucoup ?","Au pachisi","Au go","Aux dames","Au mancala"]],"kf":["Un jeu de course aztèque : on lance cinq haricots marqués et l’on avance des pions sur un plateau en croix","Lié aux paris et aux prières adressées aux dieux, il fut interdit par les moines espagnols","Il ressemble de façon frappante au pachisi indien, mais on pense que les deux sont nés séparément"],"more":[{"h":"Un chemin en croix de 52 cases","p":["Le plateau de patolli est un chemin en croix peint sur une étoffe, une natte ou un sol de pierre. Les reconstitutions donnent le plus souvent à chaque bras deux voies de cases qui, avec les quatre cases du centre, font 52.","Cinquante-deux, c’est aussi le nombre d’années du cycle calendaire aztèque, et certains chercheurs voient dans le plateau une image du calendrier ou du temps qui passe. On faisait faire un tour complet à ses pions ; le premier rentré gagnait."],"cap":["Un plateau de patolli tel qu’on le reconstitue souvent : quatre bras de deux voies de six cases, plus quatre cases centrales, 52 en tout. Les cases rouges au bout des bras seraient spéciales"]},{"h":"Cinq haricots","p":["Au lieu de dés, on lançait cinq haricots marqués d’un trou ou d’un signe sur une face, et l’on avançait d’autant de cases que de marques visibles. Les cinq marques ne sortent qu’une fois sur 32.","On raconte qu’avant de lancer, on parlait aux haricots et l’on invoquait Macuilxochitl, dieu des jeux. Le Codex Magliabechiano, du XVIe siècle, montre des joueurs autour d’un patolli sous le regard du dieu."],"cap":["Sur cinq haricots, combien tombent face marquée en haut (0–5) et à quelle fréquence (sur 32), si chacun tombe d’un côté ou de l’autre à égalité"]},{"h":"Le sosie du pachisi","p":["Des pions qui tournent autour d’un plateau en croix, des déplacements fixés par le nombre de pièces lancées tombées face visible : le patolli et le pachisi ou le chaupar de l’Inde se ressemblent étonnamment. En 1878, l’anthropologue britannique Tylor y vit non un hasard, mais la preuve que le jeu venait d’Asie.","Pourtant, aucune trace d’une telle traversée des océans n’a été trouvée. On pense aujourd’hui que des peuples éloignés sont parvenus chacun de leur côté aux mêmes idées : un chemin qui fait le tour, et des objets à lancer."],"cap":["Peinture du chaupar en Inde (1694–95) : des pions qui font le tour d’un plateau en croix, comme au patolli"]}],"tl":[["époque de Teotihuacan","Des plateaux en croix sont gravés dans des sols de pierre"],["1519–21","L’Espagne conquiert les Aztèques"],["XVIe s.","Le Codex Magliabechiano montre le patolli et Macuilxochitl"],["vers 1577","Sahagún consigne le patolli dans le Codex de Florence"],["vers 1581","Durán décrit les prières et les paris"],["1878","Tylor défend une origine asiatique"],["1977","Un plateau est découvert parmi des gravures rupestres du Jalisco"]]},"xiangqi":{"title":"Le fleuve et le canon du xiangqi","lead":"Un « fleuve » au milieu et un canon qui saute pour prendre : quand les échecs chinois ont-ils pris leur forme actuelle ?","s":["Le xiangqi est le jeu d’échecs chinois, joué sur les points d’une grille de 9×10. Ses pièces sont des disques portant des caractères, qui se déplacent sur les lignes et non dans des cases comme aux échecs.","Un premier indice est le Xuanguai lu, recueil de récits étranges du ministre Tang Niu Sengru (779–847). Le rêve d’un homme sur une armée minuscule cite un cheval céleste, un général, des chars et des fantassins, avec des allusions à une catapulte. Mais le plateau et les coups ne sont pas ceux d’aujourd’hui.","La forme actuelle — plateau de 9×10, fleuve et canon — apparaît dans des sources de la dynastie Song (960–1279). Un jeu complet de pièces a été trouvé dans une tombe des Song du Nord à Luoyang.","Le fleuve porte souvent l’inscription « Fleuve Chu, frontière Han », d’après la ligne entre le Chu de Xiang Yu et le Han de Liu Bang dans leur guerre du IIIe siècle av. J.-C. Le général ne peut quitter son palais, et les deux généraux ne doivent jamais se faire face sans rien entre eux.","Le canon ne prend qu’en sautant exactement une pièce. Le xiangqi est très aimé au Viêt Nam sous le nom de cờ tướng, et en Corée il a donné un proche cousin, le janggi. Dans l’Atlas, on peut jouer aux deux."],"quiz":[["Où se déplacent les pièces du xiangqi ?","Sur les points des lignes","Dans des cases","Autour d’un cercle","Sur des hexagones"],["Sous quelle dynastie le xiangqi actuel apparaît-il dans les sources ?","Song","Han","Ming","Qing"],["Comment le canon prend-il ?","En sautant une pièce","Un pas tout droit","Deux pas en diagonale","Seulement après le fleuve"]],"kf":["Les échecs chinois : des pièces rondes marquées de caractères s’affrontent sur les points d’une grille de 9 × 10 lignes","Une « rivière » traverse le milieu et chaque camp a un « palais » pour son général ; chaque pièce a son terrain","Fixé dans sa forme actuelle sous les Song, il est encore joué par des dizaines de millions de personnes en Chine et au Vietnam"],"more":[{"h":"Un plateau avec rivière et palais","p":["Chaque camp a 16 pièces : un général, 2 conseillers, 2 éléphants, 2 chevaux, 2 chars, 2 canons et 5 soldats. Rouges et noirs écrivent certaines pièces de même rôle avec des caractères un peu différents.","Le général et les conseillers ne peuvent sortir du palais, et les éléphants ne peuvent franchir la rivière. Les soldats n’avancent que tout droit avant la rivière ; une fois passée, ils peuvent aussi aller de côté. Un cheval ne peut sauter si une pièce se trouve juste à côté de lui dans la direction voulue. Le plateau lui-même façonne le rôle de chaque pièce."],"cap":["Position de départ du xiangqi. Noirs en haut, rouges en bas. Les caractères 楚河 漢界 marquent la rivière ; les zones de 3 × 3 à diagonales sont les palais"]},{"h":"Le canon qui saute","p":["Le canon se déplace d’ordinaire comme le char, de n’importe quelle distance le long d’une ligne. Mais pour prendre, il doit sauter exactement une pièce intermédiaire, de n’importe quelle couleur, appelée l’écran.","L’usage des écrans crée une tactique sans équivalent ailleurs. Placer un canon sur la colonne centrale dès le début, le « canon central », reste l’une des ouvertures les plus jouées."],"cap":["La prise du canon : le canon rouge saute exactement une pièce intermédiaire — le cheval noir — pour prendre le char noir au-delà"]},{"h":"Recueils et maîtres","p":["Sous les Ming parurent de nombreux recueils de belles parties et de problèmes. Le Shiqing yaqu (1570) et le Juzhong mi (1632) sont des classiques encore étudiés.","Au XXe siècle, Hu Ronghua remporta dix fois de suite le championnat national chinois, et en 1993 naquit la Fédération mondiale de xiangqi, avec des tournois internationaux. Dans les parcs de Chine et du Vietnam, des cercles de curieux se forment chaque jour autour des joueurs."],"cap":[]}],"tl":[["IXe s.","Le Xuanguai lu de Niu Sengru mentionne généraux, chars et chevaux"],["Song (960–1279)","La forme actuelle, plateau de 9 × 10, rivière et canon, apparaît dans les textes"],["Song du Nord","Un jeu complet de pièces est déposé dans une tombe de Luoyang"],["1570","Le recueil de parties Shiqing yaqu"],["1632","Le recueil de parties Juzhong mi"],["années 1960–70","Hu Ronghua remporte dix titres nationaux d’affilée"],["1993","Fondation de la Fédération mondiale de xiangqi"]]},"backgammon":{"title":"Le backgammon a-t-il 5 000 ans ?","lead":"Le plateau dit « le plus ancien backgammon » et les vrais ancêtres du jeu : d’une cour perse aux clubs de New York.","s":["La « Ville brûlée » de Shahr-e Sukhteh, en Iran, a livré un plateau vieux d’environ 5 000 ans, avec 60 pions et des dés, souvent appelé le plus ancien backgammon. Mais ses cases sont formées par les anneaux d’un serpent sculpté, une vingtaine : une forme différente du jeu actuel.","L’ancêtre direct probable du backgammon est le nard perse, apparu entre le IIIe et le VIe siècle. Un récit en moyen-perse, écrit entre le VIIe et le IXe siècle, raconte que le ministre Bozorgmehr, après avoir résolu l’énigme des échecs envoyés d’Inde, inventa le nard en retour.","Rome avait son propre jeu de plateau à trois dés, la tabula — la malheureuse partie de l’empereur Zénon du récit 3. Cette famille des « tables » s’est répandue dans toute l’Europe et a donné de nombreux cousins, comme le trictrac français.","Le nom « backgammon » apparaît dans l’Angleterre du XVIIe siècle, et en 1743 Edmond Hoyle en publia les règles et la stratégie.","La dernière grande invention, le cube de doublement, serait née dans des clubs new-yorkais dans les années 1920. En permettant de doubler l’enjeu en cours de partie, elle a fait du backgammon un jeu profond où il faut savoir quand presser."],"quiz":[["Quelle forme a le plateau de Shahr-e Sukhteh ?","Des cases formées par un serpent enroulé","La même que le backgammon actuel","Un disque rond","Une croix"],["Selon le récit, qui inventa le nard ?","Le ministre Bozorgmehr","L’empereur Zénon","Edmond Hoyle","Alphonse X"],["Qu’est-ce qui serait né à New York dans les années 1920 ?","Le cube de doublement","Les deux dés","Les 24 flèches","Les quinze dames"]],"kf":["Quinze dames par camp courent sur 24 flèches au gré de deux dés ; le premier à les sortir toutes gagne","Ses ancêtres directs sont le nard persan et la tabula romaine, de la famille des « tables »","Le videau et les ordinateurs lui ont donné une profondeur nouvelle au XXe siècle"],"more":[{"h":"Quinze dames et 24 flèches","p":["Le tablier compte 24 longs triangles, ou flèches, et chaque joueur a 15 dames. On lance deux dés et l’on avance une dame de chaque nombre, ou une seule des deux. Un double se joue quatre fois.","S’arrêter sur une dame adverse isolée la « frappe » et l’envoie sur la barre au centre ; elle doit rentrer par le jan intérieur adverse. Quand ses quinze dames sont dans son jan, on commence à les sortir, et le premier à vider le tablier gagne."],"cap":["Position de départ du backgammon. Les blancs vont de 24 à 1 (sens inverse des aiguilles d’une montre) ; les flèches 1–6, en bas à droite, forment leur jan intérieur. Les noirs vont en sens inverse"]},{"h":"Plus c’est près, plus on touche","p":["Pouvoir frapper une dame isolée dépend beaucoup de la distance. À six flèches, 17 lancers sur 36 touchent ; à sept, seulement 6.","Connaître ces chiffres dit où une dame est en danger. Au départ, chaque joueur a besoin de 167 points de dés pour ramener et sortir toutes ses dames ; les bons joueurs comptent ce « pip count » pour juger qui mène."],"cap":["Combien des 36 lancers de deux dés peuvent frapper une dame isolée à 1–12 flèches de distance (sans obstacle)"]},{"h":"Des clubs aux championnats du monde","p":["En 1743, Edmond Hoyle publia en Angleterre un livre de règles et de stratégie. Dans la Grande-Bretagne du XIXe siècle, on aimait assez le jeu pour le peindre sur des meubles, et dans les clubs new-yorkais des années 1920 naquit le videau.","Un championnat du monde se tint aux Bahamas en 1964, et le jeu connut un boom dans les années 1970. En 1979, le programme de Hans Berliner battit le champion du monde Luigi Villa ; vers 1992, TD-Gammon, qui apprenait en jouant contre lui-même, approcha le niveau des meilleurs humains."],"cap":["Meuble peint de deux joueurs de backgammon (Londres, 1861), l’une des premières pièces de Morris, Marshall, Faulkner & Co."]}],"tl":[["vers 3000 av. J.-C.","Un plateau en serpent enroulé, des pions et des dés sont enterrés à Shahr-e Sukhteh"],["vers IIIe–VIe s.","Le nard apparaît en Perse"],["1743","Hoyle publie son livre sur le backgammon"],["années 1920","Naissance du videau à New York"],["1964","Championnat du monde aux Bahamas"],["1979","Le programme de Berliner bat le champion du monde"],["vers 1992","Apparition de TD-Gammon, qui apprend en jouant contre lui-même"]]},"hex":{"title":"Le Hex, inventé deux fois","lead":"Un poète danois et un jeune génie américain ont imaginé le même jeu, chacun sans connaître l’autre.","s":["Au Hex, on pose à tour de rôle des pierres sur un losange d’hexagones ; celui qui relie ses deux côtés opposés gagne. C’est tout.","Le premier à l’imaginer fut le mathématicien et poète danois Piet Hein. En 1942, il le présenta à l’Institut Niels Bohr de Copenhague ; le 26 décembre de la même année, le journal Politiken le publia sous le nom de « Polygon », vendu en blocs de 50 feuilles.","En 1943, Hein dut quitter le Danemark et le jeu s’effaça. Quelques années plus tard, en 1948–49, John Nash, étudiant à Princeton, inventa le même jeu de façon tout à fait indépendante ; ses camarades l’appelaient « Nash ».","En 1952, Parker Brothers le commercialisa sous le nom de « Hex », et en 1957 Martin Gardner le présenta dans sa chronique de Scientific American, le faisant connaître dans le monde entier.","Le Hex ne peut jamais finir sur une nulle. Et Nash a prouvé que le premier joueur a toujours une stratégie gagnante — sans dire laquelle. Sur les grands plateaux, cette manière de gagner reste inconnue."],"quiz":[["Comment gagne-t-on au Hex ?","En reliant ses deux côtés","En prenant toutes les pierres","En encerclant le roi","En alignant cinq pierres"],["Comment s’appelait le jeu de Hein dans le journal danois ?","Polygon","Nash","Con-tac-tix","Othello"],["Qu’a prouvé Nash ?","Le premier peut toujours gagner","Le second gagne toujours","C’est toujours nul","Les coups gagnants exacts"]],"kf":["On pose à tour de rôle des pions sur des cases hexagonales ; on gagne en reliant ses deux bords opposés","Inventé séparément par Piet Hein au Danemark en 1942 et par John Nash aux États-Unis en 1948–49","Pas de nulle, et le premier joueur gagne, c’est prouvé — mais sur les grands plateaux, nul ne sait comment"],"more":[{"h":"Un jeu où il suffit de relier","p":["Le plateau est un losange de cases hexagonales ; la taille officielle est 11 × 11. Rouge défend le haut et le bas, Bleu la gauche et la droite, et ils posent un pion chacun à leur tour. Les pions ne bougent jamais et ne sont jamais pris.","Quand le plateau est plein, l’un des deux est forcément relié. Les hexagones ne se touchent jamais par un seul coin : impossible de se faufiler à travers la ligne adverse. En 1979, le mathématicien David Gale a montré que cette propriété « sans nulle » équivaut à un célèbre résultat mathématique, le théorème du point fixe de Brouwer."],"cap":["Un plateau de hex 7 × 7. Rouge gagne en reliant haut et bas, Bleu en reliant gauche et droite. Les pions rouges cerclés d’or ont relié le haut au bas"]},{"h":"Ponts et échelles","p":["Un outil favori des bons joueurs est le pont. Si l’on pose un pion non pas à côté du précédent mais une case plus loin, les deux partagent deux cases voisines vides. Si l’adversaire en bouche une, on prend l’autre : en pratique, ils sont déjà reliés.","Près des bords, on connaît de nombreuses formes fixes, comme les « échelles » de pions qui longent le côté pour l’atteindre. Le premier joueur étant trop avantagé, on utilise d’ordinaire la règle d’échange : après le premier coup, le second joueur peut s’approprier ce pion."],"cap":["Le « pont ». Les deux pions rouges peuvent se relier par l’une ou l’autre des deux cases vides entre eux (cercles pointillés). Si Bleu en prend une, Rouge prend l’autre"]},{"h":"Un jeu de mathématiciens","p":["Nash a prouvé que le premier joueur gagne par un argument de « vol de stratégie » : si le second avait une stratégie gagnante, le premier pourrait se l’approprier, ce qui est contradictoire. Une preuve étrange, qui ne montre aucun coup gagnant.","Dans les années 1950, Claude Shannon, père de la théorie de l’information, construisit une machine qui jouait au hex grâce à un circuit électrique. Dans les années 2010, les ordinateurs ont résolu tous les plateaux jusqu’à 9 × 9, mais le plateau officiel de 11 × 11 reste non résolu."],"cap":[]}],"tl":[["1942","Hein publie « Polygon » dans un journal danois"],["1948–49","Nash, à Princeton, invente le même jeu"],["1952","Parker Brothers le commercialise sous le nom de « Hex »"],["années 1950","Shannon construit une machine électrique qui joue au hex"],["1957","Gardner le présente dans sa chronique"],["1979","Gale montre son lien avec le théorème du point fixe"],["années 2010","Les plateaux jusqu’à 9 × 9 sont résolus par ordinateur"]]},"foxgeese":{"title":"Le renard, les oies et les pions d’argent du roi","lead":"Un renard, beaucoup d’oies : la longue histoire d’un « jeu de chasse » où les deux camps ne sont pas égaux.","s":["Au renard et aux oies, un seul renard saute par-dessus les oies pour les manger, tandis que les oies cherchent à l’enfermer pour qu’il ne puisse plus bouger. Les deux camps ont des règles différentes, sur un plateau en croix de 33 points reliés par des lignes.","Un indice ancien est le « halatafl » de la saga islandaise de Grettir, écrite vers le XIVe siècle. Le mot signifie « plateau de la queue », la queue étant sans doute celle du renard. C’était probablement une branche des jeux nordiques de tafl.","En Angleterre, les comptes du roi Édouard IV, au XVe siècle, mentionnent l’achat de « deux renards et 26 chiens d’argent doré » : des pions pour deux jeux, alors appelés semble-t-il « renard et chiens ».","Avec les 13 oies d’origine, le renard était trop fort ; des façons de jouer avec plus d’oies se sont donc répandues. Au XIXe siècle, la reine Victoria aurait aimé ce jeu.","Le même plateau en croix sert au solitaire, jeu pour un joueur. Les jeux de chasse où un tigre ou un loup poursuit sa proie, comme le bagh-chal népalais, existent dans le monde entier. Dans l’Atlas, on peut jouer au renard et aux oies comme au solitaire."],"quiz":[["Que signifie « hala » dans halatafl ?","Queue","Renard","Roi","Neige"],["Quels pions figurent dans les comptes d’Édouard IV ?","Des renards et des chiens d’argent","Des oies en or","Un roi d’ivoire","Des dés en bois"],["Quel jeu pour un joueur utilise le même plateau en croix ?","Le solitaire","Le sudoku","La réussite (cartes)","Le tangram"]],"kf":["Un renard contre 13 oies (plus tard 17) sur un plateau en croix de 33 points","Le renard prend en sautant ; les oies gagnent en l’acculant pour qu’il ne puisse plus bouger","Le même plateau sert au solitaire, et l’on trouve des jeux de chasse de ce genre partout dans le monde"],"more":[{"h":"Un contre treize","p":["Le renard avance d’un pas le long des lignes et prend en sautant une oie voisine si le point suivant est vide ; comme aux dames, il peut enchaîner les sauts. Les oies ne prennent pas et, dans bien des versions, ne peuvent reculer.","Les oies cherchent à se serrer sans laisser de trou, à acculer le renard et à le priver de tout coup. Avec treize oies, le renard serait trop avantagé ; avec dix-sept oies qui ne reculent pas, un jeu juste ferait gagner les oies."],"cap":["Plateau du renard et des oies : 33 points en croix reliés par des lignes. Treize oies en haut ; le renard (orange) peut prendre l’oie juste devant lui (×) en sautant jusqu’au point vide derrière"]},{"h":"La famille des jeux de chasse","p":["Quelques pièces fortes chassant beaucoup de faibles : ces jeux de chasse existent partout. Au bagh-chal népalais, quatre tigres chassent vingt chèvres sur un plateau de 5 × 5 ; en 2004, le calcul a montré qu’avec un jeu parfait, la partie est nulle.","L’assaut, populaire dans l’Allemagne du XIXe siècle, utilise le même plateau en croix : deux officiers contre vingt-quatre soldats. Les officiers y défendent une forteresse que les soldats tentent de prendre."],"cap":["Les jeux de chasse en chiffres : chasseurs à gauche (orange), proies à droite (blanc). De haut en bas : renard et oies (1:13), la version à plus d’oies (1:17), le bagh-chal du Népal (4:20) et l’assaut (2:24)"]},{"h":"Des pions du roi au solitaire","p":["Les comptes d’Édouard IV d’Angleterre (règne 1461–83) mentionnent l’achat de pièces en argent doré pour un jeu de renard et de chiens. C’était aussi un passe-temps de rois et de nobles.","Le même plateau en croix à 33 trous sert au solitaire, qui se joue seul. Une gravure française de 1697 montre une grande dame y jouant : l’un des plus anciens témoignages du solitaire."],"cap":[]}],"tl":[["vers le XIVe s.","Le « hala-tafl » apparaît dans la Saga de Grettir islandaise"],["fin XVe s.","Édouard IV achète des pièces d’argent pour renard et chiens"],["1697","Une gravure française montre une dame jouant au solitaire"],["XIXe s.","La reine Victoria aurait aimé ce jeu"],["XIXe s.","L’assaut, sur le même plateau, est en vogue en Allemagne"],["2004","Le bagh-chal népalais est montré nul en jeu parfait"]]},"latrunculi":{"title":"Le jeu des soldats romains","lead":"Un jeu qui passionnait les Romains, nommé d’après les soldats à gages. Aucune règle écrite ne survit : seulement des poèmes, des anecdotes et des plateaux sortis de terre.","s":["Le ludus latrunculorum était un jeu de bataille à deux de la Rome antique. Latrunculi désignait d’abord des mercenaires ou des brigands, et les pions figuraient des soldats.","Les pions se déplaçaient sur une grille, et un pion pris entre deux pions ennemis était capturé. Un poème du Ier siècle, la Laus Pisonis, décrit des pions qui avancent et reculent, et un pion cerné jusqu’à ne plus pouvoir bouger.","Le philosophe Sénèque raconte l’histoire de Julius Canus, condamné à mort par l’empereur Caligula. Quand le centurion vint le chercher, Canus jouait aux latrunculi ; il compta les pions et dit à son adversaire de ne pas prétendre, après sa mort, avoir gagné.","On a trouvé des plateaux dans tout l’empire. Les grilles gravées dans les pierres des forts et des villes vont d’environ 8 × 8 à 12 × 12. Une tombe du Ier siècle à Stanway, en Angleterre, contenait des pions de verre encore disposés sur leur plateau.","Aucune règle détaillée ne nous est parvenue : les règles actuelles sont des reconstitutions de chercheurs. Le latrunculi de l’Atlas s’appuie sur l’une d’elles."],"quiz":[["Comment capture-t-on un pion aux latrunculi ?","En l’enfermant entre deux pions","En sautant par-dessus","Par un lancer de dés","En entourant le roi"],["Qui jouait aux latrunculi quand on vint le chercher pour l’exécuter ?","Julius Canus","César","Néron","Cicéron"],["Qu’est-ce qui reposait encore sur le plateau dans la tombe de Stanway ?","Des pions de verre","Des pièces d’or","Des pièces d’échecs","Des cartes à jouer"]],"kf":["Un jeu de bataille à deux de la Rome antique, aux pions vus comme des soldats","Un pion pris entre deux ennemis est capturé ; les pions bloqués sont aussi évoqués","Sans règle écrite, il est reconstitué d’après des poèmes, des anecdotes et des plateaux exhumés"],"more":[{"h":"Enfermer et cerner","p":["La source la plus riche pour les reconstitutions est la Laus Pisonis, poème du Ier siècle. Elle décrit le jeu comme un champ de bataille : un pion avance pour attirer l’ennemi, un autre protège ses arrières, et celui qui se trouve pris entre deux ennemis est perdu.","Le poème parle aussi d’un pion cerné, incapable de bouger ; aussi bien des reconstitutions ajoutent-elles une règle pour les pions bloqués en plus de la prise par encadrement. Les jeux de tafl nordiques connaissent une prise très semblable."],"cap":["La capture aux latrunculi (reconstitution). À gauche : en avançant comme la flèche bleue, on enferme le pion blanc entre deux noirs et on le prend (×). À droite : un pion blanc bloqué sur ses quatre côtés ne peut plus bouger"]},{"h":"Un plateau à deux faces","p":["Dans un poème accompagnant un cadeau, le poète Martial (Ier siècle) décrit un plateau où, d’un côté, les pions avancent selon les dés et, de l’autre, s’affrontent des soldats de deux couleurs : un jeu de hasard et un jeu de réflexion sur une seule planche.","La face aux dés serait le jeu de course dit des « douze lignes », ancêtre de la tabula et du backgammon. La tour à dés (pyrgus) de la collection du musée est un autre objet qu’utilisaient les Romains."],"cap":["Le plateau à deux faces de Martial, tel qu’on l’imagine : d’un côté une course de douze lignes aux dés, de l’autre la grille des soldats"]},{"h":"Des plateaux sortis de terre","p":["Les soldats romains gravaient des grilles dans les pierres et les sols de leurs forts pour jouer. On a trouvé des plateaux gravés près du mur d’Hadrien en Bretagne, ainsi qu’en Allemagne, en Espagne et en Afrique du Nord.","Dans la tombe de Stanway (milieu du Ier siècle), le plateau de bois avait pourri, mais les pions de verre blancs et bleus étaient restés en place, comme en pleine partie. Leur propriétaire était peut-être médecin : des instruments médicaux furent enterrés avec eux."],"cap":["Une tour à dés (pyrgus). Les Romains y lançaient les dés pour empêcher la triche"]}],"tl":[["Ier s. av. J.-C.","Varron mentionne les latrunculi"],["fin Ier s. av. J.-C.","Ovide évoque le jeu dans sa poésie amoureuse"],["Ier s.","La Laus Pisonis décrit le jeu en vers"],["milieu Ier s.","Un plateau garni de ses pions est enterré à Stanway"],["Ier s.","Sénèque raconte l’anecdote de Julius Canus"],["fin Ier s.","Martial évoque un plateau à deux faces"],["1994","Schädler publie une reconstitution des règles"]]},"amazons":{"title":"Le jeu qui brûle son propre plateau","lead":"Né en Argentine en 1988, le jeu des Amazones marie le déplacement de la dame des échecs et le décompte de territoire du go.","s":["Le jeu des Amazones se joue à deux sur un plateau de 10 × 10, avec quatre « amazones » par camp. Il a été inventé en 1988 par l’Argentin Walter Zamkauskas.","Un coup se fait en deux temps. D’abord une amazone se déplace comme la dame des échecs, en ligne droite horizontale, verticale ou diagonale ; puis, depuis sa case d’arrivée, elle tire une flèche de la même façon. La case touchée par la flèche ne peut plus jamais être traversée.","Chaque coup remplit une case de plus, et le joueur qui ne peut plus jouer perd. Il n’y a pas de partie nulle.","En fin de partie, les flèches cloisonnent le plateau en pièces séparées. Gagne alors celui qui possède le plus de cases vides à lui : on évalue la position en comptant le territoire, comme au go.","Il existe plus de 2 000 premiers coups possibles, ce qui rend le jeu difficile même pour les ordinateurs. Les mathématiciens l’étudient, et c’est une épreuve des tournois d’ordinateurs."],"quiz":[["Dans quel pays le jeu des Amazones est-il né ?","L’Argentine","Le Brésil","L’Espagne","Le Mexique"],["Que devient la case où l’on tire une flèche ?","Plus personne ne peut la traverser","Elle disparaît au tour suivant","Elle devient une pièce adverse","Elle rapporte un point"],["Qui perd au jeu des Amazones ?","Le premier qui ne peut plus jouer","Le premier qui perd une pièce","Le premier qui fait un territoire","Celui qui dépasse son temps"]],"kf":["Un jeu à deux sur un plateau de 10 × 10, né en Argentine en 1988","L’amazone se déplace comme une dame, puis tire une flèche qui brûle une case","Qui ne peut plus jouer perd ; à la fin, on compte le territoire comme au go"],"more":[{"h":"Se déplacer, puis tirer","p":["Une amazone peut parcourir autant de cases qu’elle veut, sans franchir une autre pièce ni une flèche. De sa case d’arrivée, elle tire ensuite une flèche, elle aussi en mouvement de dame — même vers la case qu’elle vient de quitter.","On ne prend jamais rien. Chaque coup ferme plutôt une case du plateau et barre les chemins de l’adversaire : attaque et défense se décident d’une seule et même flèche."],"cap":["Un coup au jeu des Amazones. L’amazone blanche se déplace comme une dame (bleu), puis tire une flèche de la même façon (rouge). La case de la flèche est fermée pour de bon"]},{"h":"Un plateau découpé en pièces","p":["Au fil de la partie, les flèches cloisonnent le plateau. Si une pièce ne contient que les amazones d’un seul joueur, ses cases vides lui appartiennent, à dépenser une par coup.","La partie devient alors un décompte : qui a le plus de cases utilisables peut jouer plus longtemps. Cela se prête bien à la théorie des jeux combinatoires, et Elwyn Berlekamp, entre autres, a étudié de près les finales des Amazones."],"cap":["Fin de partie (illustration). Des murs de cases brûlées découpent le plateau en quatre pièces : les vertes ne servent qu’aux Blancs, les bleues qu’aux Noirs. Qui a le plus de cases vides peut jouer le plus longtemps"]},{"h":"Né dans une revue, disputé par des ordinateurs","p":["Le jeu serait d’abord paru dans une revue argentine d’énigmes. Ses règles sont courtes et il suffit d’un échiquier et de quelques pièces : il s’est répandu dans le monde par Internet.","Avec plus de 2 000 premiers coups possibles, l’ouverture demande une vision de tout le plateau, comme au go. Depuis les années 2000, c’est une épreuve des tournois d’ordinateurs, où les programmes s’affrontent."],"cap":[]}],"tl":[["1988","Walter Zamkauskas invente le jeu des Amazones"],["années 1990","Il se répand dans le monde par Internet"],["2000","Berlekamp publie des travaux mathématiques sur ses finales"],["années 2000","Il devient une épreuve de l’Olympiade des ordinateurs"]]},"loa":{"game":"Lines of Action","title":"Des pions qui avancent autant qu’on compte","lead":"Lines of Action est né dans un livre de Sid Sackson en 1969. On ne gagne pas en capturant : on gagne en réunissant tous ses pions en un seul groupe.","s":["Lines of Action (LOA) est un jeu à deux sur un plateau de 8 × 8, avec douze pions par camp. Inventé par Claude Soucie, il a été présenté en 1969 dans A Gamut of Games, un livre du collectionneur de jeux Sid Sackson.","Un pion avance en ligne droite, horizontalement, verticalement ou en diagonale. Il parcourt exactement autant de cases qu’il y a de pions — les siens comme ceux de l’adversaire — sur cette ligne. Chaque coup modifie les comptes, donc les distances.","On peut sauter par-dessus ses propres pions, jamais par-dessus ceux de l’adversaire. Si l’on s’arrête sur un pion adverse, on le capture.","Le but est de réunir tous ses pions en un seul groupe, qui se touchent horizontalement, verticalement ou en diagonale. Capturer réduit l’armée adverse, ce qui peut même l’aider à se rassembler : une curieuse subtilité.","Les règles sont courtes mais le jeu est difficile à calculer, si bien qu’il sert depuis longtemps à la recherche en IA des jeux. Des programmes de l’université de Maastricht, aux Pays-Bas, ont remporté de nombreux tournois entre ordinateurs."],"quiz":[["Qu’est-ce qui décide du nombre de cases parcourues par un pion ?","Le nombre de pions sur cette ligne","Le résultat d’un dé","Le nombre de pions déjà capturés","C’est toujours trois cases"],["Comment gagne-t-on à LOA ?","En réunissant tous ses pions en un seul groupe","En capturant tous les pions adverses","En atteignant le bord opposé","En prenant le roi adverse"],["Qui a présenté LOA dans un livre en 1969 ?","Sid Sackson","Martin Gardner","Edmond Hoyle","H. J. R. Murray"]],"kf":["Jeu à deux sur un plateau de 8 × 8, douze pions chacun ; inventé par Claude Soucie et présenté dans un livre de Sid Sackson en 1969","Un pion avance d’exactement autant de cases qu’il y a de pions sur sa ligne ; il peut sauter les siens, jamais ceux de l’adversaire","Le vainqueur n’est pas celui qui capture le plus, mais celui qui réunit le premier tous ses pions en un groupe"],"more":[{"h":"Compter, puis avancer","p":["Si, par exemple, trois pions se trouvent sur la rangée qui passe par un pion, celui-ci avance d’exactement trois cases le long de cette rangée, ni plus ni moins. Il peut passer au-dessus de ses propres pions, mais si un pion adverse se trouve entre les deux, il ne peut pas aller dans cette direction.","Chaque pion se trouve sur quatre lignes — une rangée, une colonne et deux diagonales —, chacune avec son propre compte. Quand un pion bouge, les comptes de plusieurs lignes autour de lui changent : les « distances » du plateau sont rebattues à chaque coup. C’est ce qui rend LOA si difficile à prévoir."],"cap":["Où peut aller le pion noir d’où partent les flèches. La rangée compte 3 pions : il avance de 3 (sauter son propre pion est permis) ; la colonne en compte 2 : il avance de 2 et capture un pion blanc. La diagonale en compte aussi 3, mais un pion blanc barre le passage (×)"]},{"h":"Un seul groupe gagne","p":["Des pions sont reliés lorsqu’ils se touchent horizontalement, verticalement ou en diagonale. Un joueur réduit à un seul pion est lui aussi « relié » : trop capturer peut même offrir la victoire à l’adversaire.","Ce qui se passe lorsqu’un coup relie les deux camps à la fois varie selon l’édition et le tournoi. La première édition du livre de Sackson parlait de partie nulle, une édition ultérieure d’une victoire pour celui qui a joué, et la plupart des tournois actuels comptent une nulle. Dans le LOA de cet Atlas, celui qui a joué gagne."],"cap":["Une position gagnante. Les pions blancs (bord doré) se touchent, diagonales comprises, et forment un seul groupe. Les noirs sont encore divisés en trois (pointillés)"]},{"h":"Un jeu que se disputent les ordinateurs","p":["Petit plateau, règles courtes, jeu profond : LOA est devenu un terrain d’essai pour l’IA des jeux. MIA, le programme de Mark Winands à l’université de Maastricht, a remporté l’Olympiade des ordinateurs en 2003, 2004, 2006 et 2009, et ses travaux sont réunis dans sa thèse de doctorat de 2004, Informed Search in Complex Games.","En 2008, Winands a résolu LOA sur un plateau réduit de 6 × 6, montrant qu’avec un jeu parfait le premier joueur (Noir) gagne. Le jeu complet de 8 × 8 serait toujours non résolu. Les joueurs humains se retrouvent aussi lors d’un championnat du monde organisé chaque année aux Mind Sports Olympiad."],"cap":[]}],"tl":[["v. 1960","Claude Soucie aurait inventé LOA"],["1969","Présenté dans A Gamut of Games de Sid Sackson"],["2003","MIA de Winands remporte l’Olympiade des ordinateurs (puis en 2004, 2006 et 2009)"],["2004","Thèse de doctorat de Winands, Informed Search in Complex Games"],["2008","LOA en 6 × 6 est résolu : victoire du premier joueur"]]},"konane":{"title":"Le jeu de lave noire et de corail blanc","lead":"Le kōnane, joué par le peuple d’Hawaï, a été décrit dans le récit du voyage de Cook ; au XXe siècle, les mathématiciens l’ont disséqué avec la théorie des jeux combinatoires.","s":["Le kōnane est un jeu à deux des Hawaïens autochtones. Des pierres noires et blanches remplissent le plateau en alternance, sans vide, et l’on capture en sautant par-dessus les pierres adverses.","Autrefois, les pierres noires étaient de lave et les blanches des éclats de corail. Le plateau, appelé papamū, était une grande pierre plate creusée de petites cupules. Le jeu apparaîtrait même dans le Kumulipo, le chant hawaïen de la création.","Noir retire d’abord une de ses pierres, puis Blanc en retire une voisine. Les deux trous ainsi formés sont le point de départ des sauts.","Chaque coup est une capture. Une pierre saute horizontalement ou verticalement par-dessus une pierre adverse voisine et se pose sur la case vide derrière. Tant qu’elle va tout droit, elle peut continuer à sauter.","Celui qui n’a plus de capture perd ; il n’y a pas de nulle. Ce principe simple a plus tard attiré les mathématiciens."],"quiz":[["En quoi étaient les anciennes pierres blanches du kōnane ?","En corail","En ivoire","En marbre blanc","En os"],["Qui perd au kōnane ?","Celui qui n’a plus de capture","Celui dont toutes les pierres sont prises","Le premier à atteindre le bord","Celui à qui il ne reste qu’une pierre"],["Lors de sauts enchaînés, qu’est-ce qui est interdit ?","Changer de direction en chemin","Prendre plus d’une pierre en un tour","S’arrêter en route","Se poser à côté d’une de ses pierres"]],"kf":["Jeu à deux des Hawaïens autochtones, qui commence avec des pierres noires (lave) et blanches (corail) alternées sur tout le plateau","Chaque coup saute horizontalement ou verticalement une pierre adverse et la prend ; en ligne droite, on peut ressauter","Celui qui n’a plus de capture perd ; les mathématiciens l’ont étudié avec la théorie des jeux combinatoires"],"more":[{"h":"Sauter et prendre","p":["Les sauts se font seulement horizontalement ou verticalement, jamais en diagonale. Si la case derrière une pierre adverse voisine est vide, la pierre saute, s’y pose, et la pierre sautée est retirée du plateau.","Si elle peut sauter de nouveau depuis sa case d’arrivée, elle peut continuer dans la même direction. Elle ne peut pas changer de direction en route, et peut s’arrêter quand elle veut. Une seule pierre bouge par tour."],"cap":["Une pierre blanche saute deux fois vers la droite en un tour et prend deux pierres noires (bleu 1 et 2). Elle ne peut pas tourner pour sauter vers le bas depuis sa case d’arrivée (×)"]},{"h":"Les deux premiers trous","p":["Sur un plateau plein de pierres, personne ne peut sauter. Noir, qui commence, retire donc une de ses pierres parmi les quatre cases centrales ou dans un coin. Blanc retire ensuite une des siennes qui touche ce trou horizontalement ou verticalement.","Les deux trous côte à côte sont les premières cases d’arrivée. L’endroit où on les ouvre façonne toute la partie."],"cap":["Les deux façons de commencer. Noir retire une de ses pierres parmi les quatre du centre (à gauche) ou dans un coin (à droite) (1), puis Blanc retire une pierre voisine (2)"]},{"h":"Plateaux de pierre et 238 cases","p":["Le récit du troisième voyage de James Cook (tome III, paru en 1784) décrit un jeu de pierres vu à Hawaï comme « très semblable à nos dames », mais plus compliqué. L’auteur en est l’officier James King, qui indique un plateau d’environ deux pieds de long, de 238 cases, quatorze par rangée.","Il n’y avait pas de taille fixe : on connaît des plateaux de 6 × 7, 9 × 13, 13 × 20 et d’autres. Aujourd’hui on joue surtout sur un plateau carré de côté pair, et cet Atlas propose 6 × 6, 8 × 8 et 10 × 10. Au parc historique national de Puʻuhonua o Hōnaunau, sur l’île d’Hawaï, on peut encore voir des papamū taillés dans la pierre."],"cap":["Tailles de plateau comparées : le 14 × 17 (238 cases) décrit dans le récit du voyage de Cook, et les 10 × 10, 8 × 8 et 6 × 6 jouables dans cet Atlas"]},{"h":"Un jeu découvert par les mathématiciens","p":["Au kōnane, celui qui ne peut plus jouer perd, et en fin de partie le plateau se divise en zones indépendantes : c’est taillé pour la théorie des jeux combinatoires d’Elwyn Berlekamp et de ses collègues. Michael Ernst a écrit avec Berlekamp un court article sur le kōnane en 1993, puis, dans un article de 1995, a calculé les valeurs de nombreuses positions.","D’autres travaux ont suivi : Alice Chan et Alice Tsai ont étudié le kōnane à une seule rangée (2002), et Bob Hearn a montré que sur des plateaux toujours plus grands, savoir qui gagne devient extrêmement difficile (PSPACE-complet). Un jeu de pierres qui sautent était devenu un sujet de la théorie de la complexité."],"cap":[]}],"tl":[["1778","Les navires de Cook atteignent Hawaï"],["1784","Publication du récit du troisième voyage de Cook, avec la description du jeu de pierres par King"],["1993","Ernst et Berlekamp écrivent un court article sur le kōnane"],["1995","Article d’Ernst « Playing Konane Mathematically »"],["2002","Chan et Tsai résument leurs résultats sur le kōnane à une rangée"]]},"peg":{"title":"Le casse-tête à sauts né à la cour","lead":"Le solitaire se jouait à la fin du XVIIe siècle à la cour de Louis XIV. Ce casse-tête tout simple, où l’on retire les fiches une à une, fascine les mathématiciens depuis.","s":["Le solitaire est un casse-tête qui se joue seul. Des fiches remplissent les trous du plateau, et un seul trou reste vide.","Une fiche saute par-dessus une voisine, horizontalement ou verticalement, jusqu’au trou vide situé derrière. La fiche sautée est retirée du plateau.","Le but est de sauter encore et encore jusqu’à ce qu’il ne reste qu’une fiche. La laisser pile au centre, c’est la fin parfaite.","Les premières traces sûres viennent de la France de la fin du XVIIe siècle, à la cour de Louis XIV. En 1697, le Mercure galant publia le plateau et ses règles, et une gravure montre une grande dame avec un plateau à ses côtés.","Il paraît facile, mais il est difficile. Le mathématicien Leibniz s’y intéressa, et au XXe siècle des mathématiciens expliquèrent, en coloriant les trous, pourquoi certains problèmes n’ont pas de solution."],"quiz":[["Que devient une fiche par-dessus laquelle on saute ?","Elle est retirée du plateau","Elle passe à l’adversaire","Elle glisse dans le trou voisin","Elle revient au tour suivant"],["Combien de trous compte le plateau anglais ?","33","37","45","64"],["D’où viennent les premières traces sûres du solitaire ?","De la cour de Louis XIV, à la fin du XVIIe siècle","Des thermes de la Rome antique","D’une école de temple du Japon d’Edo","D’un saloon de l’Amérique du XIXe siècle"]],"kf":["Un casse-tête à sauts pour un joueur : on saute pour retirer les fiches, et on gagne en n’en laissant qu’une","Les traces sûres commencent vers 1697 à la cour de Louis XIV ; les plateaux classiques ont 33 (anglais) et 37 (européen) trous","Colorier les trous en trois couleurs permet de savoir d’avance quels problèmes sont impossibles"],"more":[{"h":"Sauter et prendre","p":["On saute seulement horizontalement ou verticalement, jamais en diagonale (sauf sur les plateaux à lignes diagonales, comme le triangle). Chaque saut retire une fiche : en partant de 32, il faut 31 sauts pour n’en garder qu’une.","Une même fiche peut sauter plusieurs fois de suite. En comptant une telle série comme un seul coup, le problème « du centre au centre » du plateau anglais se résout en 18 coups. Ernest Bergholt a trouvé cette solution en 1912, et John Beasley a prouvé en 1964 qu’on ne peut pas faire moins."],"cap":["Le premier coup sur le plateau anglais. Le centre étant vide, la fiche du haut saute par-dessus celle du dessous jusqu’au centre (bleu) ; la fiche sautée est retirée (×)"]},{"h":"Un passe-temps de cour","p":["L’histoire sûre du solitaire remonte à la cour de Louis XIV vers 1697. En août de cette année-là, le Mercure galant décrivit le plateau, les règles et quelques problèmes, et le graveur Claude-Auguste Berey représenta la princesse de Soubise avec un plateau à ses côtés.","On raconte aussi qu’un noble enfermé à la Bastille l’aurait inventé pour tromper l’ennui, mais c’est une légende invérifiable. Le plateau à 37 trous utilisé en France daterait lui aussi du XVIIe siècle, tandis que celui à 33 trous, aux coins coupés, est appelé plateau anglais."],"cap":["Les deux plateaux classiques : anglais, 33 trous (à gauche), et européen, 37 trous (à droite). Le trou vide est le départ habituel de chacun"]},{"h":"Ce que révèlent trois couleurs","p":["Colorions les trous en trois couleurs qui suivent les diagonales. Alors trois trous consécutifs, en ligne ou en colonne, sont toujours de trois couleurs différentes. Un saut retire une fiche à deux couleurs et en ajoute une à la troisième : les nombres des trois couleurs changent donc ensemble de parité.","Sur le plateau européen au centre vide, chaque couleur a 12 fiches : toutes paires. Chaque saut ne fait qu’alterner entre « toutes paires » et « toutes impaires », si bien qu’on n’atteint jamais la position d’une dernière fiche — une couleur à 1, les deux autres à 0. Sur ce plateau, le problème qui part du centre n’a pas de solution. La même vérification sur le plateau anglais réduit à cinq seulement les trous où peut finir la dernière fiche en partant du centre."],"cap":["Le plateau européen à 37 trous colorié en trois couleurs le long des diagonales. Le centre étant vide, chaque couleur compte 12 fiches"]},{"h":"Un jouet pour mathématiciens","p":["Leibniz aurait écrit, dans une note de 1710, qu’il aimait jouer à rebours, en remplissant les trous par-dessus lesquels on avait sauté. Remonter depuis la fin reste une méthode de base pour résoudre le jeu.","Winning Ways (1982), de Berlekamp, Conway et Guy, a analysé le casse-tête en détail et présenté les « fonctions pagode » : en donnant à chaque trou une valeur telle qu’aucun saut n’augmente le total, on peut prouver que certains objectifs sont impossibles. En 1999, une recherche par ordinateur aurait examiné toutes les positions."],"cap":[]}],"tl":[["1697","Joué à la cour de Louis XIV ; le Mercure galant d’août publie le plateau et les règles"],["1710","Leibniz aurait écrit sur le jeu à rebours"],["1912","Bergholt trouve une solution en 18 coups sur le plateau anglais"],["1964","Beasley prouve qu’aucune solution ne fait moins de 18 coups"],["1982","Winning Ways expose son analyse, dont les fonctions pagode"]]},"fanorona":{"title":"Prendre en approchant, prendre en s’éloignant","lead":"Le fanorona est le jeu national de Madagascar. La légende dit qu’il a décidé d’un trône — et au XXIe siècle, des ordinateurs ont montré qu’en jouant parfaitement, la partie est nulle.","s":["Le fanorona est un jeu à deux très répandu à Madagascar. Il se joue sur un plateau de 9 × 5 tracé de lignes horizontales, verticales et diagonales, avec 22 pions par camp.","Le plateau ressemble à deux plateaux d’alquerque — un jeu du monde arabe et de l’Europe — posés côte à côte. On pense que l’alquerque est arrivé sur l’île et y est devenu un jeu à part entière.","Sa grande particularité est la prise. En s’approchant d’un pion adverse (« approche ») ou en s’en éloignant (« retrait »), on prend toute la file de pions adverses sur cette ligne.","La prise est obligatoire, et un pion qui a pris peut changer de direction et prendre encore. Un seul tour peut bouleverser le plateau : c’est tout le sel du fanorona.","Aimé depuis des siècles, il a même sa légende d’un prince qui perdit un trône faute de pouvoir quitter une partie. En 2007, des chercheurs néerlandais ont montré par ordinateur qu’avec le meilleur jeu des deux côtés, la partie est nulle."],"quiz":[["Quelle est la taille du plateau de fanorona ?","9 × 5","8 × 8","7 × 7","6 × 6"],["Quelles sont les deux façons de prendre au fanorona ?","L’approche et le retrait","Le saut et l’encadrement","L’encerclement et la poussée","Les dés et le tirage au sort"],["Qu’ont montré les ordinateurs avec le meilleur jeu ?","Une partie nulle","Une victoire du premier joueur","Une victoire du second joueur","On ne sait encore rien"]],"kf":["Jeu à deux de Madagascar : 22 pions chacun sur un plateau de 9 × 5, seul le centre vide au départ","S’approcher d’un pion adverse (approche) ou s’en éloigner (retrait) prend toute la file sur cette ligne","En 2007, des ordinateurs ont montré qu’avec le meilleur jeu la partie est nulle"],"more":[{"h":"L’approche et le retrait","p":["Dans l’approche, si le point juste après l’arrivée porte un pion adverse, ce pion et tous les pions adverses alignés derrière lui sans interruption sont pris. Le retrait est l’inverse : on prend le pion adverse situé juste derrière le point de départ et ceux alignés derrière lui.","Comme un seul pas peut retirer plusieurs pions à la fois, les armées fondent dès le début. Quand un coup permet à la fois une approche et un retrait, le joueur choisit l’un des deux."],"cap":["Les deux prises. En haut : Blanc avance d’un pas vers la droite en s’approchant d’un pion noir et prend les trois noirs alignés au-delà (approche). En bas : Blanc avance vers la droite en s’éloignant d’un noir et prend les deux noirs derrière lui (retrait)"]},{"h":"Deux plateaux d’alquerque côte à côte","p":["Le plateau compte 5 × 9 = 45 points ; outre les lignes horizontales et verticales, des diagonales passent par un point sur deux. Les pions avancent d’un pas le long d’une ligne vers un point voisin. Au départ, seul le centre est vide : le premier coup est donc toujours une prise.","Le plateau, ce sont deux plateaux d’alquerque de 5 × 5 réunis. L’alquerque est un jeu ancien déjà cité dans un livre arabe du Xe siècle, et l’on pense que le fanorona en est issu. On ignore quand et comment il est arrivé sur l’île ; certains livres parlent du XVIIe siècle."],"cap":["La position de départ : 22 pions noirs et 22 blancs sur les 9 × 5 points, seul le point central est vide. Les carrés en pointillé marquent deux plateaux d’alquerque de 5 × 5"]},{"h":"Les chaînes de prises","p":["Un pion qui a pris peut reprendre. Mais chaque pas doit aller dans une direction différente, et il ne peut pas revenir sur un point déjà visité. Continuer ou non est au choix du joueur.","Quand une telle chaîne réussit, un seul tour peut enlever près de la moitié des pions adverses. Mais si elle s’arrête au mauvais endroit, le pion est aussitôt repris."],"cap":["Une chaîne de prises. Blanc (1) s’approche vers la droite et prend deux pions ; (2) se retire vers le haut et en prend deux ; (3) s’approche vers la gauche et en prend deux. Après (1), il ne peut pas continuer vers la droite (×)"]},{"h":"Un trône et des ordinateurs","p":["Selon la légende, Ralambo, roi de l’Imerina vers le XVIe siècle, feignit la maladie pour que le premier fils rentré hérite du trône. L’aîné, Andriantompokoindrindra, ne put quitter une position de fanorona difficile, et le cadet, Andrianjaka, devint roi. Un autre récit veut que, lors de l’invasion française de 1895, le camp de la reine s’en soit remis à une partie rituelle de fanorona ; aucun des deux ne peut être confirmé.","En 2007, Maarten Schadd et ses collègues de l’université de Maastricht, aux Pays-Bas, ont calculé toutes les positions à sept pions ou moins et, par une recherche par nombres de preuve, ont montré que la position de départ est nulle (l’article a paru en 2008). Le calcul a pris plus d’une semaine sur une seule machine."],"cap":[]}],"tl":[["v. XVIe s.","La légende de la succession du roi Ralambo et du fanorona"],["v. XVIIe s.","Une hypothèse sur la naissance du fanorona à partir de l’alquerque"],["1895","La légende d’une partie rituelle de fanorona pendant l’invasion française"],["2007","Schadd et ses collègues montrent par ordinateur que la partie est nulle"],["2008","L’article « Best Play in Fanorona Leads to Draw »"]]},"janggi":{"title":"Un plateau sans rivière et un canon qui ne saute qu’une fois","lead":"Le janggi, très aimé en Corée, utilise le même plateau de 9 × 10 que le xiangqi chinois — mais il a supprimé la rivière et changé la marche des pièces.","s":["Le janggi est un jeu d’échecs à deux pratiqué depuis longtemps en Corée. On pense qu’il vient du xiangqi chinois ; ses pièces se placent sur les points d’un quadrillage de 9 × 10 lignes.","Contrairement au xiangqi, le plateau n’a pas de « rivière » au milieu : éléphants et soldats peuvent aller partout. Le général (roi) commence au centre de son « palais » et ne peut jamais en sortir.","Les camps sont Cho (bleu ou vert) et Han (rouge). Les pièces sont octogonales, et plus une pièce est forte, plus elle est grande. Cho joue en premier.","Avant la partie, chaque camp choisit l’une des quatre façons de placer chevaux et éléphants. Han se place d’abord et Cho décide après l’avoir vu : le marchandage commence avant le premier coup.","Outre le mat, une partie peut se décider aux points. Cho, qui commence, part de 72 points ; Han reçoit un « deom » de 1,5 point et part de 73,5. Chaque pièce perdue fait baisser le total."],"quiz":[["Que n’a pas le plateau de janggi ?","Une rivière au milieu","Des palais","Des diagonales dans les palais","90 points"],["Que doit toujours faire le canon pour se déplacer ?","Sauter exactement une pièce","Se trouver à côté d’une pièce adverse","Être dans un palais","Ne pas être en échec"],["Aux points, combien de « deom » reçoit Han, le second joueur ?","1,5","0,5","3","6,5"]],"kf":["Les échecs de Corée, nés du xiangqi : un plateau de 9 × 10, mais sans rivière","L’éléphant fait un pas droit puis deux en diagonale ; le canon se déplace et prend en sautant exactement une pièce","Chaque camp choisit l’un des quatre placements des chevaux et éléphants ; aux points, Han reçoit un deom de 1,5"],"more":[{"h":"Un plateau sans rivière et quatre placements","p":["Le plateau de janggi a les mêmes 9 × 10 points que le xiangqi, mais pas de rivière. Chaque palais porte des diagonales en X, et le général et les gardes s’y déplacent d’un pas, y compris le long des diagonales. Le général commence au centre même de son palais.","Il y a quatre placements, obtenus en échangeant chevaux et éléphants. Han se place d’abord, Cho choisit après l’avoir vu. Mettre les éléphants à l’intérieur ou à l’extérieur change les lignes d’attaque de l’ouverture."],"cap":["Le plateau de janggi et la position de départ. Pas de rivière ; les palais du haut et du bas ont des diagonales. Les cercles en pointillé marquent où chevaux et éléphants peuvent être échangés ; Han (en haut) et Cho (en bas) ont choisi des placements différents"]},{"h":"Cheval, éléphant et points bloqués","p":["Le cheval fait d’abord un pas en ligne droite, puis un pas en diagonale vers l’extérieur. L’éléphant va plus loin : un pas droit, puis deux en diagonale. Pour les deux, une pièce sur un point du trajet bloque cette direction.","L’éléphant du xiangqi ne peut pas traverser la rivière et ne fait que deux pas en diagonale, mais celui du janggi a de longues jambes et parcourt tout le plateau. En échange, son chemin se bloque facilement."],"cap":["Le cheval (à gauche) fait un pas droit puis un en diagonale ; l’éléphant (à droite) un pas droit puis deux en diagonale. Les points bleus montrent où ils peuvent aller. Une pièce sur un point du trajet bloque cette direction (×)"]},{"h":"Le canon qui ne saute qu’une fois","p":["Le canon doit sauter exactement une pièce intermédiaire, pour se déplacer comme pour prendre. S’il n’y a rien entre les deux, il ne peut pas bouger : dans la position de départ, les canons sont immobiles.","Ni la pièce sautée ni la pièce prise ne peuvent être un canon ; deux canons ne peuvent donc que se toiser. Comparé au canon du xiangqi, qui se déplace librement quand il ne prend pas, c’est une pièce bien plus exigeante."],"cap":["Le canon. En haut : il saute exactement un soldat et va sur un point au-delà, ou prend le char (bleu). Au milieu : il ne peut pas sauter si la pièce intermédiaire est un canon. En bas : un canon ne peut pas prendre un canon (×)"]},{"h":"Généraux face à face et points","p":["Quand les deux généraux se font face sur une ligne sans rien entre eux, on parle de « bikjang ». Selon une règle, si le camp ainsi confronté ne rompt pas ce face-à-face, la partie est nulle. Les règles traditionnelles permettent aussi de passer son tour quand on n’est pas en échec.","Les valeurs sont : char 13, canon 7, cheval 5, éléphant 3, garde 3, soldat 2. Cho totalise 72 points, Han 73,5 avec le deom. Grâce au demi-point, une égalité aux points est impossible. Dans le janggi de cet Atlas, ces points décident de la partie quand une position se répète trois fois ou après 200 coups."],"cap":[]}],"tl":[["Période Goryeo","Selon une opinion, on y jouait déjà (la date d’arrivée est discutée)"],["XVIIIe s.","Une variante sur plus grand plateau, le gwangsanghui, serait attestée"],["1895","Korean Games de Stewart Culin montre une image d’hommes jouant au janggi"],["2009","Le premier tournoi international se serait tenu à Harbin, en Chine"]]},"pic":{"tlvmirror":"Miroir TLV (Han orientaux, musée d’art de Cleveland)","kotoboard":"Les Quatre Arts (époque d’Edo, vers 1620-1650, musée d’art de Cleveland)","homerbg":"Winslow Homer, Backgammon (gravure sur bois, vers 1877, musée d’art de Cleveland)","trictrac":"Philips de Koninck, Les Joueurs de trictrac (dessin, vers 1660, musée d’art de Cleveland)","gametable":"Table de jeu à échiquier et marelle (Mayence, vers 1735, musée d’art de Cleveland)","kota":"Le souverain de Kota adorant Krishna ; sur les marches, un tapis de chaupar en croix (vers 1825, musée d’art de Cleveland)"},"mahjong":{"game":"Mah-jong","title":"Le jeu de tuiles qui porte le nom d’un moineau","lead":"Le mah-jong est né dans la Chine du XIXe siècle. Un jeu de cartes devenu jeu de tuiles, il a fait fureur dans l’Amérique des années 1920 et s’est mué au Japon en riichi mahjong.","s":["Le mah-jong est un jeu de tuiles à quatre. Il compte 136 tuiles (144 avec les fleurs), et le premier qui complète une main d’une forme donnée l’emporte.","Il est né dans la Chine du XIXe siècle. Ses racines sont des jeux de « pioche et défausse » joués avec des cartes figurant des unités de monnaie ; on pense que vers le milieu du siècle les cartes de papier sont devenues des tuiles.","Les plus anciennes tuiles conservées datent des environs de 1870 et ont été acquises à Ningbo, Shanghai et Fuzhou. Certains livres le font naître à Ningbo, d’autres y voient un passe-temps de pêcheurs du Fujian et du Guangdong.","« Máquè » veut dire moineau, et une théorie fait venir le nom d’un jeu de cartes plus ancien, le madiao. L’histoire souvent répétée selon laquelle Confucius l’aurait inventé n’a aucun fondement.","Au XXe siècle, le mah-jong traverse les mers. Il fait fureur dans l’Amérique des années 1920, et au Japon la règle du « riichi », apparue plus tard, en fait un jeu à part entière."],"quiz":[["Sans les fleurs, combien de tuiles compte le mah-jong ?","136","144","108","152"],["Quelle est la forme de base d’une main gagnante ?","Quatre combinaisons et une paire","Sept combinaisons seulement","Treize tuiles identiques","Trois combinaisons et deux paires"],["Dans quel pays le mah-jong a-t-il fait fureur dans les années 1920 ?","Les États-Unis","La Russie","Le Brésil","L’Égypte"]],"kf":["Un jeu de tuiles à quatre né de jeux de cartes dans la Chine du XIXe siècle","Tuiles numérotées en caractères, ronds et bambous, plus vents et dragons ; on gagne avec quatre combinaisons et une paire","Une mode dans l’Amérique des années 1920 ; dans le Japon d’après-guerre est né le riichi mahjong"],"more":[{"h":"136 tuiles","p":["Les tuiles numérotées forment trois familles — caractères, ronds et bambous —, chacune de 1 à 9 en quatre exemplaires : 108 tuiles. Ajoutez quatre de chaque vent (est, sud, ouest, nord) et de chaque dragon (blanc, vert, rouge) : on arrive à 136.","Beaucoup de façons de jouer en Chine utilisent aussi huit fleurs : prunier, orchidée, chrysanthème et bambou, et les quatre saisons. Elles n’entrent pas dans la main ; piochées, on les pose à part et elles rapportent des points. Le mah-jong japonais s’en passe d’ordinaire."],"cap":["Les sortes de tuiles. Caractères, ronds et bambous de 1 à 9, les vents (est, sud, ouest, nord) et les dragons (blanc, vert, rouge), quatre de chaque : 136. Avec les huit fleurs sous la ligne pointillée (une de chaque) : 144"]},{"h":"Quatre combinaisons et une paire","p":["La main compte 13 tuiles ; on pioche une tuile et on en défausse une, encore et encore. Quand une tuile piochée, ou défaussée par un autre, complète quatre combinaisons et une paire, la main gagne.","Les combinaisons sont le chow (trois nombres qui se suivent dans une famille), le pung (trois tuiles identiques) et le kong (quatre identiques). On peut aussi les former en prenant la défausse d’un autre joueur : la partie est une longue lutte pour choisir quoi prendre et quoi lâcher."],"cap":["La forme de base d’une main gagnante : quatre combinaisons — chow (trois qui se suivent dans une famille), pung (trois identiques) ou kong (quatre identiques) — et une paire"]},{"h":"Le mah-jong traverse les mers","p":["En 1920, Joseph Park Babcock publia un livre de règles en anglais, et une boutique new-yorkaise se mit à importer des jeux de Chine. Le mah-jong fit fureur dans l’Amérique des années 1920, et la National Mah Jongg League, fondée en 1937, perpétue une façon américaine de jouer.","Il arriva au Japon dans les années 1920 ; Saburo Hirayama aurait ouvert en 1924 une salle et une école à Tokyo, et en 1929 fut fondée la Ligue japonaise de mah-jong, présidée par l’écrivain Kan Kikuchi. En 1952, après la guerre, Daizō Amano aurait publié dans un journal des règles avec « riichi », point de départ du riichi mahjong japonais."],"cap":["La diffusion du mah-jong : de la Chine vers l’Amérique et le Japon dans les années 1920 ; règles du riichi au Japon en 1952 et règles officielles chinoises en 1998"]},{"h":"Légendes et histoire réelle","p":["Le mah-jong a bien des légendes d’origine. Celle qui l’attribue à Confucius n’a aucune base. Celle d’un homme de Ningbo nommé Chen Yumen qui l’aurait inventé est sans doute inventée elle aussi, car les papiers dont elle proviendrait n’ont jamais été retrouvés.","Ce qui est sûr, c’est que des jeux chinois de pioche et défausse du XIXe siècle, joués avec des cartes d’argent, sont devenus un jeu de tuiles. Les premiers jeux n’avaient ni fleurs ni dragon vert, mais des tuiles « roi » et d’autres. En 1998, la Chine a aussi fixé des règles officielles nationales."],"cap":[]}],"tl":[["milieu du XIXe s.","Les jeux de cartes seraient devenus un jeu de tuiles"],["v. 1870","Les plus anciens jeux conservés (Ningbo, Shanghai, Fuzhou)"],["1920","Babcock publie un livre de règles en anglais"],["1929","Fondation de la Ligue japonaise de mah-jong"],["1952","Publication des « règles Hochi » avec riichi"],["1998","La Chine fixe des règles officielles nationales"]],"figL":{"hand":["Chow","Pung","Kong","Chow","Paire"],"spread":[["v. 1870","Ningbo, Shanghai","Plus vieilles tuiles"],["1920","États-Unis","Règles de Babcock, la mode"],["1920s","Japon","Arrivée ; ligue en 1929"],["1952","Japon","Règles du riichi"],["1998","Chine","Règles officielles, 81 figures"]]}},"gomoku":{"title":"Le gomoku, quand le premier joueur était trop fort","lead":"Le gomoku, qui se joue avec un goban et des pierres de go, est aimé au Japon depuis l’époque d’Edo. Pour freiner l’avantage du premier joueur sont nées les règles du « renju » — et les ordinateurs ont fini par donner la réponse.","s":["Le gomoku est un jeu à deux qui se joue avec un goban et des pierres. Noir et Blanc posent une pierre à tour de rôle, et le premier qui aligne cinq de ses pierres — en ligne, en colonne ou en diagonale — gagne.","Son origine est obscure. Certains la font remonter à la Chine antique ou au Japon de Heian, mais les traces sûres datent de l’époque d’Edo, et l’on y jouait, dit-on, dès le milieu du XVIIIe siècle.","Plus on jouait, plus il devenait clair que Noir, qui commence, était avantagé. Au Japon, on a donc peu à peu créé des règles imposant des « coups interdits » au seul Noir.","En 1899, Ruikō Kuroiwa, du journal Yorozu chōhō, baptisa le jeu « renju », c’est-à-dire « perles enfilées ».","En 1988, la Fédération internationale de renju (RIF) a été fondée à Stockholm, en Suède, et des championnats du monde ont lieu. Les ordinateurs, eux, ont montré que le gomoku sans coups interdits est gagné par le premier joueur."],"quiz":[["Comment gagne-t-on au gomoku ?","En alignant cinq de ses pierres","En encerclant et prenant des pierres","En occupant plus de la moitié du goban","En prenant cinq pierres adverses"],["Qui a donné au jeu le nom de « renju » ?","Ruikō Kuroiwa","Honinbō Dōsaku","Natsume Sōseki","Fukuzawa Yukichi"],["Au renju, quels coups sont interdits au seul Noir ?","Double trois, double quatre et ligne trop longue","Jouer sur le bord du goban","Jouer à côté d’une pierre blanche","Encercler des pierres adverses"]],"kf":["Un jeu à pierres de go : cinq alignées gagnent ; les traces sûres commencent à l’époque d’Edo","Noir commençant avec l’avantage, le renju lui interdit le double trois, le double quatre et la ligne de six ou plus","En 1994, le gomoku libre sur 15 × 15 a été prouvé gagnant pour le premier joueur"],"more":[{"h":"Cinq alignés et le quatre-trois","p":["Les parties se décident par une double menace que l’adversaire ne peut pas parer d’un coup. Un « quatre » — à une pierre de cinq — doit être bloqué aussitôt, sinon c’est perdu. Un « trois » ouvert aux deux bouts, si on l’ignore, devient un quatre ouvert impossible à arrêter.","Un coup qui crée à la fois un quatre et un trois — un « quatre-trois » — oblige Blanc à boucher le quatre ; le trois grandit ensuite et gagne. Progresser au gomoku, c’est voir venir cette forme de plus en plus tôt."],"cap":["À gauche : cinq en diagonale gagnent. À droite : la pierre cerclée de rouge crée à la fois un « quatre » en ligne (jouer en 4 donne cinq) et un « trois » ouvert en colonne (les points 3) : Blanc ne peut pas tout parer (quatre-trois)"]},{"h":"Des coups interdits au seul Noir","p":["Au renju, Noir ne peut jouer ni double trois, ni double quatre, ni ligne trop longue (six ou plus) ; c’est une faute, et il perd. Blanc n’a aucun coup interdit, et même six pierres ou plus alignées le font gagner.","Pour gagner, Noir doit bâtir des formes comme le quatre-trois qui ne soient pas interdites. Blanc peut même pousser Noir exprès vers un coup interdit : une bataille d’esprit qui fait la profondeur du renju."],"cap":["Coups interdits à Noir au renju (×). De gauche à droite : le « double trois » (deux trois d’un coup), le « double quatre » (deux quatre d’un coup) et la « ligne trop longue » (six ou plus)"]},{"h":"Le gomoku résolu","p":["En 1994, le Néerlandais Victor Allis a prouvé par ordinateur qu’au gomoku libre sur un goban de 15 × 15, le premier joueur, Noir, gagne toujours. En 2001, Wágner et Virág ont montré que le renju sans règles d’ouverture est lui aussi gagné par le premier joueur.","On joue encore parce que les lignes gagnantes sont bien trop complexes pour être mémorisées. Les tournois utilisent des « règles d’ouverture » fixant la façon de jouer les premiers coups — comme Yamaguchi ou Soosõrv-8 — pour que la lutte soit équitable."],"cap":["L’histoire du gomoku et du renju : du gomoku de l’époque d’Edo au nom de renju, à la fédération internationale et aux preuves par ordinateur"]},{"h":"Cinq en ligne dans le monde entier","p":["Au XIXe siècle, le jeu est arrivé en Grande-Bretagne sous le nom de « Go Bang ». Aujourd’hui, des jeux proches se jouent partout : l’omok coréen, le caro vietnamien, ou le pente, où l’on prend des pierres par paires.","Le gomoku de cet Atlas se joue sur un goban de 15 × 15, avec trois règles au choix : renju, standard et libre. Comparez-les et voyez combien les coups interdits du renju brident le premier joueur."],"cap":[]}],"tl":[["milieu du XVIIIe s.","On jouerait au gomoku dans le Japon d’Edo"],["1856","Le plus ancien livre de gomoku conservé, le Gomoku Jōseki"],["1899","Ruikō Kuroiwa nomme le jeu renju"],["1988","Fondation de la Fédération internationale de renju à Stockholm"],["1994","Allis prouve que le gomoku libre est gagné par le premier joueur"],["2001","Wágner et Virág montrent que le renju sans règles d’ouverture est gagné par le premier"]],"figL":{"time":[["1700s","Japon (Edo)","On joue au gomoku"],["1899","Japon","Nommé « renju »"],["1988","Stockholm","Naissance de la RIF"],["1994","Pays-Bas","Gomoku : le 1er gagne"],["2001","Hongrie","Renju : Noir gagne"]]}},"carrom":{"title":"Le carrom : une pichenette jusqu’à la poche","lead":"En Inde et en Asie du Sud, familles et voisins se retrouvent pour jouer au carrom. Les pions, lancés d’une pichenette, filent vers les poches des quatre coins du plateau : un jeu proche du billard.","s":["Le carrom se joue sur un plateau lisse d’environ 74 centimètres de côté. Chaque coin a une poche ; on joue à deux face à face, ou à quatre par équipes de deux.","Il y a 19 pions : 9 blancs, 9 noirs et une « reine » rouge. À votre tour, vous posez le « palet de frappe », plus grand et plus lourd, sur la ligne devant vous — la ligne de base — et vous l’envoyez d’une pichenette vers les pions.","On gagne en empochant tous les pions de sa couleur. Mais la reine rouge n’est à vous que si, après l’avoir empochée, vous empochez aussitôt l’un de vos pions pour la « couvrir ».","Le carrom viendrait d’Inde ; un plateau à surface de verre est encore exposé dans un palais de Patiala, dans le nord du pays. Au début du XXe siècle, l’Inde organisait déjà des tournois d’État.","En 1988, la Fédération internationale de carrom a été fondée à Chennai, en Inde, et des championnats du monde ont lieu depuis 1991. Des jeux de pichenette semblables existent partout, du crokinole canadien au novuss letton."],"quiz":[["Sans compter le palet de frappe, combien de pions compte le carrom ?","19","16","24","32"],["Comment la reine rouge devient-elle vôtre ?","En empochant ensuite un de ses pions (la couvrir)","En l’empochant en dernier","En l’empochant au premier coup","En la touchant deux fois de suite"],["Dans quelle ville la Fédération internationale de carrom a-t-elle été fondée en 1988 ?","Chennai","Londres","Colombo","Bombay"]],"kf":["Un plateau avec une poche à chaque coin : d’une pichenette, le palet de frappe envoie les pions dans les poches","9 blancs, 9 noirs et une reine rouge ; la reine doit être « couverte » en empochant ensuite un de ses pions","Né en Inde, dit-on ; Fédération internationale en 1988, championnats du monde depuis 1991"],"more":[{"h":"Le plateau et ses 19 pions","p":["Chaque coin du plateau a une poche munie d’un filet, et une double ligne de base est tracée le long de chaque côté. Le palet de frappe se pose en touchant les deux lignes, et l’on tire depuis là.","Au départ, la reine se place au centre et les pions blancs et noirs l’entourent en fleur. Le premier coup, qui disperse la fleur, est la « casse » qui lance la partie."],"cap":["Le plateau de carrom et la position de départ. La reine rouge au centre, les pions blancs et noirs autour en forme de fleur. Des poches aux coins, une double ligne de base de chaque côté ; le palet de frappe (anneau bleu) se pose sur la ligne de base proche"]},{"h":"Pichenette et rebond","p":["On lance le palet de frappe d’un coup d’ongle ; certains utilisent le majeur, l’index ou le pouce. Si vous empochez un de vos pions, vous rejouez ; sinon, c’est à l’adversaire.","Les bandes rebondissent bien : on joue les rebonds comme au billard. Empocher son propre palet de frappe est une faute, pénalisée."],"cap":["Le palet de frappe est lancé (bleu), rebondit sur la bande droite et frappe un pion blanc, qui file dans la poche en haut à droite (rouge). Un pion qu’on ne peut viser directement s’atteint par la bande"]},{"h":"Une famille de jeux de pichenette","p":["Des jeux de pichenette comme le carrom existent dans le monde entier. Le crokinole canadien vise un trou au centre d’un plateau rond, et la pichenotte se joue depuis longtemps au Canada. Le carrom lui-même serait arrivé en Amérique du Nord à la fin du XIXe siècle avec des missionnaires revenus d’Asie.","Le novuss de Lettonie et d’Estonie serait apparu dans les années 1920 ; on y frappe les palets avec une petite queue plutôt qu’avec le doigt. Il est devenu l’un des sports les plus populaires de Lettonie, et des championnats internationaux ont lieu depuis 1993."],"cap":["Cousins du carrom joués du doigt ou avec une petite queue : le crokinole et la pichenotte du Canada, le novuss de Lettonie et d’Estonie, la couronne de Scandinavie"]},{"h":"Points et championnats du monde","p":["Selon les règles internationales, couvrir la reine rapporte 3 points, et le premier à 25 points l’emporte. En famille, on joue bien des variantes locales, comme une reine à 5 points.","Des tournois sérieux auraient commencé au Sri Lanka vers 1935, et en 1958 l’Inde et le Sri Lanka avaient des fédérations officielles. La Fédération internationale de carrom (ICF) est née à Chennai en 1988, et les championnats du monde se tiennent depuis 1991."],"cap":[]}],"tl":[["début du XXe s.","Tournois d’État en Inde"],["v. 1935","Des tournois sérieux commenceraient au Sri Lanka"],["1958","L’Inde et le Sri Lanka ont des fédérations officielles"],["1988","Fondation de la Fédération internationale de carrom à Chennai"],["1991","Premier championnat du monde de carrom"]],"figL":{"family":[["Carrom","Inde · Asie du Sud"],["Crokinole","Canada"],["Pichenotte","Canada"],["Novuss","Lettonie · Estonie"],["Couronne","Suède · Danemark"]]}},"crokinole":{"title":"Viser le trou au milieu","lead":"Le crokinole est très apprécié dans le Canada rural. On y lance d’une pichenette des palets sur un plateau rond en bois, en visant le petit trou du milieu. Le plus ancien plateau connu date de 1876.","s":["Le crokinole se joue sur un plateau rond en bois d’environ 66 centimètres de diamètre. On joue à deux face à face, ou à quatre par équipes de deux, en envoyant ses palets d’une pichenette vers le centre.","Le plateau porte des cercles : de l’extérieur vers l’intérieur, des anneaux de 5, 10 et 15 points, et au centre un petit trou de 20. Huit chevilles en bois entourent l’anneau de 15 et barrent le chemin direct.","Viser le centre ne suffit pas. Si un palet adverse est sur le plateau, votre tir doit en toucher un ; sinon, votre palet est retiré.","Le plus ancien plateau connu a été fabriqué en 1876 en Ontario, au Canada, par l’artisan Eckhardt Wettlaufer, dit-on pour les cinq ans de son fils. Il se trouve aujourd’hui dans un musée de Kitchener.","Le nom viendrait du français « croquignole », une pichenette. Depuis 1999, un championnat du monde se tient chaque juin à Tavistock, où vivait Wettlaufer."],"quiz":[["Combien de points vaut le trou au centre du plateau de crokinole ?","20","15","10","50"],["Si un palet adverse est sur le plateau, que doit faire votre tir ?","Toucher un palet adverse","Entrer dans le trou central","Sortir du plateau","Toucher une cheville"],["Quand et où a été fabriqué le plus ancien plateau de crokinole connu ?","Canada, 1876","France, 1776","États-Unis, 1926","Angleterre, 1676"]],"kf":["Un plateau rond en bois : on lance des palets vers les anneaux de 5, 10 et 15 et le trou de 20 au centre","Si un palet adverse est sur le plateau, il faut le toucher ; sinon, votre palet est retiré","Le plus ancien plateau : Ontario (Canada), 1876 ; championnat du monde depuis 1999"],"more":[{"h":"Anneaux, chevilles et fossé","p":["On tire depuis l’anneau extérieur de 5, dans son propre quart. Au-delà du bord court un fossé où finissent les palets qui tombent ou qui sont retirés.","Un palet qui tombe dans le trou de 20 est aussitôt sorti et compte 20. À la fin, les palets restés sur le plateau valent 5, 10 ou 15 selon leur anneau, et l’on ne marque en général que la différence entre les deux camps."],"cap":["Le plateau de crokinole : anneaux de 5, 10 et 15 de l’extérieur vers l’intérieur, et le trou de 20 au centre. Huit chevilles gardent l’anneau de 15, et un fossé tout autour recueille les palets retirés"]},{"h":"Toucher, ou être retiré","p":["S’il y a ne serait-ce qu’un palet adverse sur le plateau, votre tir doit toucher un palet adverse, directement ou par l’intermédiaire d’un autre. Sinon, le palet tiré et ceux de vos palets déplacés par le tir sont retirés.","Quand il n’y a aucun palet adverse, beaucoup de règles exigent que le palet tiré s’arrête dans l’anneau de 15 ou touche sa ligne. Personne ne peut donc simplement se cacher, et la partie devient un duel d’attaque et de défense."],"cap":["La règle du tir. À gauche : avec un palet adverse (noir) sur le plateau, il suffit de le toucher avec votre palet (rouge) (✓). À droite : si vous le manquez, votre palet est retiré du plateau (×)"]},{"h":"D’un plateau de l’Ontario à un championnat du monde","p":["La première mention canadienne remonterait à 1867, et aux États-Unis Joshua K. Ingalls a breveté un jeu semblable en 1880. On a aussi évoqué des liens avec des jeux de pichenette de Grande-Bretagne et d’Asie du Sud, comme le carrom.","On dit parfois que c’est un jeu de mennonites ou d’amish, mais ce serait une idée reçue sans fondement. Les mennonites d’origine russe l’auraient toutefois longtemps pratiqué sous le nom de Knipsbrat, « planche à pichenettes »."],"cap":["Le crokinole au fil du temps : de la première mention canadienne au plateau de Wettlaufer, à un brevet américain et au championnat du monde de Tavistock"]},{"h":"Championnats et jeu","p":["Le championnat du monde a lieu depuis 1999 le premier samedi de juin à Tavistock. Une association internationale a été fondée en 2009, et des clubs existent dans toute l’Amérique du Nord et en Europe.","Le crokinole de cet Atlas se joue uniquement en 3D, avec plusieurs aspects de plateau au choix. Essayez-le pour le plaisir de la pichenette, comme au carrom, et celui de viser des anneaux, comme aux fléchettes."],"cap":[]}],"tl":[["1867","La première mention canadienne daterait de cette année"],["1876","Wettlaufer fabrique un plateau pour son fils"],["1880","Aux États-Unis, Ingalls brevète un jeu semblable"],["1999","Début du championnat du monde à Tavistock"],["2009","Fondation d’une association internationale"]],"figL":{"time":[["1867","Canada","Première mention"],["1876","Ontario","Le plus ancien plateau"],["1880","États-Unis","Brevet d’Ingalls"],["1999","Tavistock","Début du mondial"],["2009","International","Association internationale"]]}},"ugolki":{"title":"Saute, saute, jusqu’au coin d’en face","lead":"L’ugolki russe, le halma américain et les « dames chinoises » sur leur plateau en étoile forment une même famille : on ne prend rien, on saute par-dessus les pions jusqu’à ce que les deux armées aient échangé leurs coins.","s":["Ugolki signifie « les coins » en russe. Les Blancs et les Noirs rangent leurs pions en bloc dans deux coins opposés d’un plateau de 8×8, et le premier à amener tous ses pions dans le coin de l’autre gagne.","À chaque coup, on avance d’un pas vers une case voisine vide, ou l’on saute par-dessus un pion voisin jusqu’à la case vide juste derrière. On peut sauter ses propres pions comme ceux de l’adversaire, et enchaîner les sauts tant qu’on le peut. Rien n’est pris : les pions sautés restent sur le plateau.","Le plus connu de ces jeux est le halma américain. On dit qu’il fut imaginé vers 1883–84 par le chirurgien George Howard Monks, à partir de quelques idées d’un jeu anglais appelé Hoppity. Son nom vient du grec « saut ».","En 1892 apparut en Allemagne une version sur plateau en étoile, le « Stern-Halma » (halma étoilé). En 1928, la firme américaine Pressman le vendit sous le nom de « Chinese checkers » (dames chinoises), et ce fut un engouement ; mais le jeu n’a rien de chinois.","Personne ne sait au juste quand l’ugolki est né. Selon un récit, il aurait été inventé en Europe à la fin du XVIIIᵉ siècle, mais aucune trace sûre n’a été trouvée. Aujourd’hui, enfants et adultes y jouent en Russie et dans les pays de l’ex-Union soviétique."],"quiz":[["À l’ugolki, que devient un pion sauté ?","Il reste sur le plateau","Il est retiré","Il change de couleur","Il retourne dans son coin"],["Quand le jeu a-t-il été vendu pour la première fois comme « dames chinoises » ?","En 1928, aux États-Unis","En 1892, en Chine","Au XVIIIᵉ siècle, en Chine des Qing","Dans les années 1950, au Japon"],["Qui aurait inventé le halma ?","Monks, un chirurgien américain","Un fabricant de jouets allemand","Un mathématicien russe","Un empereur chinois"]],"kf":["D’un coin à l’autre d’un plateau de 8×8 : le premier à tout amener gagne. On ne prend rien","Un pas, ou un saut par-dessus un pion voisin — à soi ou à l’autre —, et l’on peut enchaîner","Halma (États-Unis, v. 1883–84) → Stern-Halma (Allemagne, 1892) → « dames chinoises » (1928). Rien de chinois"],"more":[{"h":"Avancer en sautant","p":["Quand on saute, peu importe à qui appartient le pion. Alignez vos pions en « échelle », servez-vous aussi de ceux de l’adversaire comme marchepieds, et un seul coup peut traverser la moitié du plateau.","Sauter n’est jamais obligatoire, et l’on peut s’arrêter en route. Mais on ne peut pas mêler un pas et un saut dans le même coup."],"cap":["Une chaîne de sauts : le pion blanc saute un noir, un blanc, un noir puis un blanc, quatre sauts en un coup (1–4). Chaque pion sauté reste sur le plateau"]},{"h":"Le plateau et les camps de l’ugolki","p":["Les camps ont plusieurs tailles : 3×3 (9 pions), 3×4 (12) et 4×4 (16). Dans les règles classiques, les pions ne se déplacent qu’en ligne droite, selon les rangées et les colonnes ; une variante permet aussi la diagonale.","Si l’on reste assis dans son propre camp, l’adversaire ne peut jamais le remplir. Aussi une règle très répandue en Russie veut-elle que perde celui qui a encore un pion dans son camp après le 40ᵉ coup. Si rien n’est décidé au 80ᵉ coup, c’est le nombre de pions dans le camp adverse qui tranche."],"cap":["Le plateau de l’ugolki : les Blancs partent du camp de 3×4 en bas à gauche (a1–d3), les Noirs en haut à droite (e6–h8), et chacun vise le coin de l’autre (flèches). Les camps peuvent aussi faire 3×3 ou 4×4"]},{"h":"La famille du halma","p":["Le halma se joue sur un plateau de 16×16, avec 19 pions chacun à deux joueurs ou 13 à quatre, qui se déplacent dans huit directions. Monks obtint un brevet américain en 1888. Le mathématicien Thomas Hill, futur président de Harvard, lui aurait donné son nom.","Le plateau en étoile compte 121 trous ; chaque joueur a d’ordinaire 10 pions, et l’on joue à deux, trois, quatre ou six. En Chine, on l’appelle tiaoqi, « jeu de sauts », et au Japon un jeu voisin s’appelle le « jeu du diamant ». Là aussi, un adversaire qui reste dans le coin que vous visez peut vous empêcher de le remplir."],"cap":["La famille des jeux où l’on saute pour changer de coin : le halma sur 16×16, le Stern-Halma et les « dames chinoises » sur l’étoile, l’ugolki sur 8×8"]},{"h":"À vous de jouer","p":["Les règles de l’ugolki s’apprennent en une minute. Mais bâtir de longues échelles avec les pions adverses aussi, sans lui laisser de marchepieds, donne une profonde bataille de calcul.","Dans cet Atlas, vous pouvez jouer à l’ugolki avec des camps de 3×3, 3×4 ou 4×4, ou avec des déplacements en diagonale. Le plateau 3D est en porcelaine blanche et bleu cobalt, comme la faïence russe de Gjel."],"cap":[]}],"tl":[["1883","Naissance du halma (v. 1883–84, États-Unis)"],["1888","Monks obtient un brevet américain pour le halma"],["1892","Le Stern-Halma sur plateau en étoile, en Allemagne"],["1928","Vendu sous le nom de « dames chinoises » aux États-Unis"],["1941","Milton Bradley obtient les droits sur le nom"]],"figL":{"fam":[["v. 1883–84","Halma","États-Unis · plateau 16×16"],["1892","Stern-Halma","Allemagne · plateau en étoile"],["1928","Dames chinoises","un nouveau nom aux États-Unis"],["date inconnue","Ugolki","Russie · plateau 8×8"]]}},"agon":{"title":"La reine sur le trône, la garde autour d’elle","lead":"L’agon se jouait dans l’Angleterre victorienne sur un plateau de cases hexagonales. Asseyez votre reine sur le trône central, entourez-la de vos six gardes, et vous avez gagné.","s":["L’agon est un jeu pour deux, aussi appelé « la Garde de la reine ». Son nom est le mot grec pour « concours ». Le plateau compte 91 cases hexagonales, et la case du centre est le trône.","Cinq anneaux entourent le trône, chacun d’une couleur différente du suivant. Chaque joueur a une reine et six gardes ; on gagne en asseyant sa reine sur le trône et en occupant les six cases qui l’entourent avec ses gardes.","Une pièce avance d’une case à la fois, le long du même anneau ou vers l’anneau intérieur. Elle ne peut jamais aller vers l’extérieur : une fois entrée, pas de retour. Seule une reine peut entrer sur le trône.","La plus ancienne trace connue est un règlement publié à Londres en 1842. Le jeu est attribué à Anthony Peacock, de Londres, et l’on y jouait dans les foyers victoriens.","On le dit souvent le plus ancien jeu de plateau connu à cases hexagonales. Selon un récit, il serait né dans la France du XVIIIᵉ siècle, mais les plateaux anciens invoqués passent pour des ajouts plus tardifs : rien n’est sûr."],"quiz":[["Comment gagne-t-on à l’agon ?","Reine sur le trône, entourée de ses six gardes","En prenant la reine adverse","En alignant toutes ses pièces au bord","En entourant le trône vide"],["Dans quelle direction une pièce d’agon ne peut-elle jamais aller ?","Vers un anneau extérieur","Le long du même anneau","Vers l’anneau intérieur","Sur le trône (si c’est une reine)"],["Quand et où les règles de l’agon ont-elles été publiées pour la première fois ?","Londres, 1842","Paris, 1742","Berlin, 1892","New York, 1942"]],"kf":["91 cases hexagonales : le trône au centre, cinq anneaux autour","Un pas le long du même anneau ou vers l’intérieur, jamais vers l’extérieur. Seule la reine prend le trône","Publié à Londres en 1842 ; souvent dit le plus ancien jeu hexagonal"],"more":[{"h":"Un plateau de trône et d’anneaux","p":["Au départ standard, reines et gardes des deux joueurs alternent sur l’anneau extérieur. Dans les règles de 1842, les reines commençaient dans des coins opposés et les gardes étaient posés un à un, à tour de rôle.","Le plateau ressemble à une cible, des anneaux de couleur autour du trône. On voit d’un coup d’œil sur quel anneau se trouve chaque pièce, ce qui aide à compter les pas qui la séparent du trône."],"cap":["Le plateau d’agon et la position de départ. La case verte du centre est le trône, entouré de cinq anneaux rouges et ivoire en alternance. La reine (couronne) et les six gardes de chaque camp alternent sur le bord"]},{"h":"Vers l’intérieur, toujours","p":["À chaque tour, on déplace une pièce d’un pas vers une case voisine vide, autour du même anneau ou vers l’intérieur.","On ne peut pas entrer sur une case située entre deux pièces adverses. Un mur de pièces ennemies est donc une vraie barrière sur la route du centre."],"cap":["Le déplacement. Le garde blanc peut avancer le long de son anneau ou vers l’anneau intérieur (vert), mais pas revenir vers l’extérieur (× rouge)"]},{"h":"Pris en sandwich, renvoyé au bord","p":["Coincez une pièce adverse en ligne droite entre deux des vôtres et elle est prise. Son propriétaire doit consacrer son tour suivant à replacer le garde pris sur une case vide de l’anneau extérieur.","Une reine prise revient sur n’importe quelle case vide sauf le trône, et elle est replacée en premier. Tous les pas gagnés à grand-peine sont perdus : la défense compte beaucoup. Les détails des règles varient un peu selon les livres."],"cap":["La prise. (1) Le garde blanc avance et coince en ligne le garde noir entre deux pièces blanches. (2) Au tour suivant de son propriétaire, le garde noir pris est replacé sur une case vide du bord"]},{"h":"À vous de jouer","p":["Si vos six gardes entourent le trône alors qu’il est vide, vous perdez sur-le-champ. Envoyer d’abord la reine, ou ouvrir la route avec les gardes ? L’ordre des coups décide de la partie.","Dans cet Atlas, vous pouvez jouer à l’agon avec le départ standard sur le bord, ou avec le départ de 1842 où l’on pose les gardes un à un. Le plateau 3D est en acajou victorien filé d’or, avec des pièces d’os et d’ébène."],"cap":[]}],"tl":[["fin du XVIIIᵉ s.","Un récit d’origine française (sans preuve solide)"],["1842","Règles d’« Agon, or the Queen’s Guards » publiées à Londres"],["XIXᵉ siècle","En vogue dans l’Angleterre victorienne ; plateaux vendus par Jaques et d’autres"],["1999","Décrit dans l’Oxford History of Board Games de Parlett"],["aujourd’hui","Intégré à Ludii, un système d’étude des jeux"]]},"dots":{"title":"Points, traits et pions qui tombent : des jeux résolus","lead":"La pipopipette, au crayon sur du papier, et le Puissance 4, où l’on laisse tomber des pions : deux jeux d’enfant que mathématiciens et ordinateurs ont entrepris de résoudre pour de bon.","s":["La pipopipette se joue sur une feuille couverte d’une grille de points. À tour de rôle, chacun relie deux points voisins par un trait ; qui trace le quatrième côté d’un carré prend cette case et rejoue. Le plus de cases gagne.","C’est le mathématicien français Édouard Lucas qui présenta le jeu sous le nom de « la Pipopipette », en 1889 selon la plupart des sources. Après sa mort, il parut aussi dans son livre L’Arithmétique amusante (1895).","Le Puissance 4 se joue en laissant tomber des pions dans un cadre vertical de 7 colonnes et 6 rangées. Le pion tombe jusqu’au trou libre le plus bas, et quatre pions de sa couleur alignés — en ligne, en colonne ou en diagonale — l’emportent. La firme américaine Milton Bradley le mit en vente en 1974 (Connect Four).","En octobre 1988, le Puissance 4 fut « résolu ». Le 1ᵉʳ James Dow Allen, puis le 16 Victor Allis, chacun de son côté, montrèrent que le premier joueur gagne toujours s’il commence dans la colonne du milieu.","Pour la pipopipette aussi, le mathématicien Elwyn Berlekamp et d’autres ont bâti une théorie des « longues chaînes », réunie en un livre en 2000. Derrière un jeu à la portée de tous se cachaient des mathématiques profondes."],"quiz":[["À la pipopipette, que fait celui qui trace le quatrième côté d’une case ?","Il prend la case et rejoue","Il passe son tour","Il donne la case","La partie s’arrête"],["Au Puissance 4, quel premier coup fait gagner le premier joueur ?","La colonne du milieu","La colonne de gauche","La colonne de droite","N’importe quelle colonne"],["Qui a résolu le Puissance 4, chacun de son côté, en 1988 ?","Allen et Allis","Lucas et Berlekamp","Wexler et Strongin","Conway et Guy"]],"kf":["Pipopipette : fermer une case, la prendre, rejouer. Qui ouvre la première longue chaîne perd le plus souvent","Puissance 4 : 7 colonnes × 6 rangées, les pions tombent en bas. En vente depuis 1974","Résolu séparément par Allen et Allis en 1988 : le premier joueur gagne depuis le centre"],"more":[{"h":"Longues chaînes et double croix","p":["Ouvrez une « chaîne » de cases reliées et l’adversaire peut toutes les prendre. La fin de partie devient donc une lutte pour savoir qui sera forcé d’ouvrir les longues chaînes. Celui qui ouvre la première longue chaîne perd le plus souvent.","Celui qui prend une chaîne peut laisser exprès les deux dernières cases à l’adversaire (la double croix). Deux cases perdues, mais l’adversaire doit ouvrir la chaîne suivante, et les grandes chaînes restantes sont pour vous."],"cap":["La bataille de la longue chaîne. (1) B ouvre une chaîne de cinq cases. A en prend trois puis, au lieu des deux dernières, trace le trait du bout (2) et les cède. (3) B prend les deux d’un seul trait, mais doit rejouer — et ouvrir la chaîne suivante"]},{"h":"Pions qui tombent, rangées paires et impaires","p":["On ne pose pas un pion où l’on veut : les colonnes se remplissent par le bas. Un trou gagnant reste donc inutilisable tant que celui du dessous est vide, et qui remplit ce trou le premier offre la victoire à l’autre.","Quand le cadre se remplit, le nombre de ces « trous que personne ne veut remplir » décide de la partie. Selon l’analyse d’Allis, les menaces sur les rangées impaires seraient fortes pour le premier joueur, et sur les rangées paires pour le second."],"cap":["Le cadre du Puissance 4. Un pion lâché en haut tombe jusqu’au trou libre le plus bas. Rouge menace sur la troisième rangée, une rangée impaire (tirets rouges). Qui remplit le trou en dessous (×) offre la victoire à rouge"]},{"h":"Chronologie des jeux résolus","p":["Le Puissance 4 est attribué aux Américains Howard Wexler et Ned Strongin. Un jeu voisin s’appelle aussi « la maîtresse du capitaine », d’après une histoire selon laquelle le capitaine Cook y jouait des heures dans sa cabine ; mais aucune preuve solide n’a été trouvée.","D’après les analyses d’Allen et d’Allis, le premier joueur qui commence au milieu gagne au plus tard au 41ᵉ coup ; commencer dans une colonne voisine mène à la nulle, et dans l’une des quatre colonnes extérieures fait gagner le second. La théorie de la pipopipette fut longuement exposée dans Winning Ways (1982)."],"cap":["Étapes vers les jeux résolus : la pipopipette de Lucas, la mise en vente du Puissance 4, l’année de sa résolution, le livre de Berlekamp"]},{"h":"À vous de jouer","p":["Connaître la réponse est une chose ; jouer contre quelqu’un en est une autre. Compter les chaînes, compter les rangées paires et impaires, garder un coup d’avance : le plaisir reste entier.","Cet Atlas propose la pipopipette et le Puissance 4. Tracez des traits sur un cahier ou une ardoise, lâchez des pions dans un cadre de cuir ou de glace, et entrevoyez ce qu’ont vu les mathématiciens."],"cap":[]}],"tl":[["1889","Lucas présente « la Pipopipette » (selon la plupart des sources)"],["1974","Milton Bradley met en vente le Puissance 4"],["1982","Winning Ways analyse la pipopipette"],["1988","Allen et Allis résolvent le Puissance 4 séparément"],["2000","The Dots and Boxes Game, de Berlekamp"]],"figL":{"time":[["1889","La Pipopipette","Lucas · France"],["1974","Puissance 4","Milton Bradley"],["1988","Puissance 4 résolu","Allen et Allis · le premier gagne"],["2000","Le livre de la pipopipette","Berlekamp"]]}},"hitblow":{"title":"Trouver les quatre cachés — la famille du Hit & Blow","lead":"Deviner quatre couleurs ou chiffres cachés avec pour seuls indices des « bien placés » et des « mal placés ». Le jeu est passé du crayon et du papier aux fiches colorées du Mastermind, puis à l’informatique.","s":["Au Hit & Blow, un joueur dispose en secret quatre couleurs ou chiffres. À chaque proposition de l’autre, on indique seulement combien sont justes en couleur et en place (hits, bien placés) et combien ont la bonne couleur à la mauvaise place (blows, mal placés).","Il vient d’un jeu de chiffres au crayon, « Bulls and Cows » (taureaux et vaches) : les bien placés sont des taureaux, les mal placés des vaches. On le dit parfois vieux d’un siècle, mais son origine réelle reste inconnue.","En 1970, Mordecai Meirowitz, receveur des postes et expert en télécommunications israélien, en fit un jeu de plateau à fiches colorées. Invicta Plastics, près de Leicester en Angleterre, en acheta les droits et le lança sous le nom de Mastermind en 1971–72 ; il fit le tour du monde.","À la même époque, les ordinateurs jouaient eux aussi à deviner des nombres. Avant 1970, une version appelée MOO fut écrite pour l’ordinateur Titan de l’université de Cambridge, puis portée en 1972 sur Multics, au MIT aux États-Unis.","En 1976–77, l’informaticien Donald Knuth montra qu’au Mastermind à 6 couleurs et 4 trous (1 296 codes en tout), de bonnes propositions trouvent toujours le code en cinq essais au plus."],"quiz":[["Quand une couleur proposée est à la même place que dans le code, comment l’appelle-t-on ?","Bien placé (hit)","Mal placé (blow)","Raté","Paire"],["Qui a inventé le Mastermind et ses fiches colorées ?","Meirowitz, en Israël","Knuth, aux États-Unis","la poste britannique","des étudiants de Cambridge"],["Combien d’essais suffisent toujours, d’après Knuth, au Mastermind à 6 couleurs et 4 trous ?","Cinq au plus","Trois au plus","Huit au plus","Dix au plus"]],"kf":["Bien placé : bonne couleur, bonne place ; mal placé : bonne couleur, mauvaise place. On ne dit jamais lesquels","Bulls and Cows au crayon → fiches colorées de Meirowitz en 1970 → Mastermind en 1971–72","Knuth (1976–77) : les 1 296 codes de 6 couleurs × 4 trous se trouvent en cinq essais au plus"],"more":[{"h":"Bien placés et mal placés","p":["Les fiches ne disent jamais quelles places étaient bonnes, seulement qu’il y a « un bien placé et deux mal placés ». On combine donc les réponses d’un essai à l’autre pour cerner le code.","Répéter un essai n’apprend rien. On choisit d’ordinaire une combinaison compatible avec toutes les réponses, mais parfois un essai qui ne peut pas être le code apporte plus d’information et raccourcit le chemin."],"cap":["Un essai et sa réponse. En haut, le code caché ; en bas, l’essai. Le premier à gauche a la bonne couleur à la bonne place : un bien placé (fiche rose). Le deuxième et le quatrième sont des couleurs du code à la mauvaise place : des mal placés (fiches blanches). Le troisième n’y est pas (×)"]},{"h":"Chaque réponse réduit le champ","p":["La méthode de Knuth choisit chaque fois l’essai qui laisse le moins de codes même si la pire réponse arrive. Son premier coup utilise deux couleurs deux fois chacune.","Des travaux ultérieurs ont aussi trouvé la méthode à la plus faible moyenne : en 1993, Koyama et Lai ont montré environ 4,34 essais en moyenne (six au pire). Le jeu de chiffres Bulls and Cows, à quatre chiffres différents, se résout toujours en sept essais."],"cap":["Un code trouvé par la méthode de Knuth. Les 1 296 codes de 6 couleurs × 4 trous tombent à 256 après le premier essai, 41 après le deuxième, 6 après le troisième et 1 après le quatrième ; le cinquième est le bon (barres en échelle logarithmique)"]},{"h":"Des chiffres aux couleurs","p":["Le Mastermind a eu beaucoup de cousins, dont le Super Mastermind à 8 couleurs et 5 trous (1972) et le Mastermind des mots, où l’on devine des lettres.","Au Japon, le jeu de devinette de chiffres s’appelle « Hit & Blow » ; il est apparu à la télévision et dans des recueils de jeux pour consoles."],"cap":["La famille dans le temps : Bulls and Cows au crayon, MOO sur l’ordinateur de Cambridge, le Mastermind de Meirowitz et le « cinq » de Knuth"]},{"h":"À vous de jouer","p":["Le meilleur moment, c’est quand, en comparant les lignes d’indices, on comprend : « cette couleur ne peut aller qu’ici ». Si chaque essai divise le champ par deux ou plus, vous jouez en maître.","Le Hit & Blow de cet Atlas propose cinq variantes — 4 couleurs parmi 6 sans répétition (360 codes), avec répétition (les 1 296 de Knuth), 3 ou 4 chiffres, et une partie experte de 5 parmi 8 couleurs — et un problème du jour."],"cap":[]}],"tl":[["1970","MOO sur l’ordinateur de Cambridge ; Meirowitz imagine le plateau à fiches"],["1971","Invicta Plastics achète les droits et lance le Mastermind"],["1972","MOO arrive sur Multics au MIT ; Super Mastermind"],["1977","Knuth : « cinq au plus » (article de 1976–77)"],["1993","Koyama et Lai : une méthode à environ 4,34 en moyenne"]],"figL":{"time":[["?","Bulls and Cows","chiffres au crayon"],["1970","MOO","l’ordinateur de Cambridge"],["1971","Mastermind","Meirowitz · Invicta"],["1977","Toujours en cinq","la preuve de Knuth"]]}},"botao":{"title":"Le foot avec les boutons du manteau","lead":"Le futebol de botão brésilien est un football de table où l’on pousse des boutons pour envoyer une minuscule balle au but. Un jeu de poche d’enfants est devenu un sport reconnu par l’État.","s":["Futebol de botão signifie « football de boutons ». Sur un terrain d’environ 167 cm de long, chaque équipe place dix boutons ronds et un bloc rectangulaire en guise de gardien, et pousse les boutons pour envoyer une balle de feutre d’1 cm dans le but adverse.","Il serait né au début du XXᵉ siècle, quand des enfants du Brésil et de Hongrie arrachaient les boutons de leurs manteaux et chemises pour jouer. En Hongrie, on l’appelle toujours gombfoci, « foot de boutons ».","Au Brésil, c’est Geraldo Décourt, un artiste de Rio de Janeiro, qui l’a codifié. En 1930 (1929 selon certaines sources), il publia le premier règlement et baptisa le jeu « Foot-Ball Celotex », du nom du revêtement du plateau.","Une fédération de l’État de São Paulo vit le jour en 1962, et en 1988 le Conseil national des sports du Brésil reconnut le « futebol de mesa » (football de table) comme sport officiel. L’anniversaire de Décourt, le 14 février, est la Journée du joueur de boutons dans l’État de São Paulo.","D’autres pays ont aussi leur football à pichenettes. En Grande-Bretagne parurent Newfooty en 1929 et Subbuteo, où l’on pousse de petites figurines, en 1947 ; et le baby-foot, aux figurines sur des barres, fut breveté dès les années 1920."],"quiz":[["De quoi se compose une équipe de futebol de botão ?","Dix boutons et un gardien","Onze boutons","Cinq boutons et un gardien","Onze figurines"],["Quand a-t-il été reconnu comme sport officiel au Brésil ?","1988","1930","1962","2001"],["Quel jeu à figurines est apparu en Grande-Bretagne en 1947 ?","Subbuteo","Newfooty","Gombfoci","Baby-foot"]],"kf":["Football de table avec dix boutons et un bloc de gardien, poussés pour mener une balle de feutre","Jeu d’enfants au début des années 1900 → règlement de Décourt en 1930 → sport officiel au Brésil en 1988","Cousins : le gombfoci hongrois, Newfooty (1929) et Subbuteo (1947) britanniques, et le baby-foot à barres"],"more":[{"h":"Pousser, annoncer, tirer","p":["On peut pousser un bouton du doigt, mais beaucoup de joueurs appuient sur son bord avec un outil plat appelé palheta, pour le faire glisser. C’est le bouton lui-même qui doit toucher la balle.","Avec la règle des 12 touches, il faut annoncer son tir à voix haute et attendre que l’adversaire place son gardien avant de tirer. Un but sans annonce ne compte pas."],"cap":["Comment on pousse un bouton. (1) On appuie sur le bord du bouton avec un outil plat ; il glisse et frappe la balle. (2) La balle passe à côté du gardien (le bloc bleu) et entre dans le but"]},{"h":"Des règles qui changent avec les touches","p":["Le Brésil a des règles traditionnelles selon les régions : le style de Bahia, une touche avec un disque ; celui de Rio, trois touches avec une balle ; celui de São Paulo, douze touches avec une balle.","À douze touches, on peut pousser jusqu’à douze fois par possession, et le même bouton jusqu’à trois fois de suite. Moins il y a de touches, moins il y a de buts ; le jeu à une touche, où l’on change de main à chaque coup, passe pour un jeu d’experts."],"cap":["Une équipe : dix boutons et un gardien rectangulaire. Les trois règles classiques du Brésil diffèrent par le nombre de poussées (touches) permises par possession"]},{"h":"La famille du foot à pichenettes","p":["Peter Adolph, le créateur de Subbuteo, s’inspira de Newfooty, né à Liverpool en 1929. Le nom vient du nom savant d’un oiseau, le faucon hobereau ; il aurait voulu l’appeler « Hobby ».","Le baby-foot, où l’on fait tourner des rangées de figurines sur des barres pour frapper la balle, fut breveté en Grande-Bretagne en 1921, et en Espagne Alejandro Finisterre fit breveter son futbolín en 1937."],"cap":["La famille du football de table à pichenettes : le gombfoci hongrois, Newfooty et Subbuteo britanniques, et le baby-foot à figurines sur barres"]},{"h":"À vous de jouer","p":["Faites progresser la balle par des passes, annoncez le tir, visez l’espace à côté du gardien : la force et l’angle d’une seule poussée décident du match.","Le futebol de botão de cet Atlas est un jeu uniquement en 3D fondé sur la règle des 12 touches. On peut choisir des matchs au nombre de coups, au nombre de buts ou aux tirs au but, et des terrains de gazon, de bois et d’autres encore."],"cap":[]}],"tl":[["début du XXᵉ s.","Des enfants de Hongrie et du Brésil jouent avec des boutons"],["1930","Premier règlement de Décourt (1929 selon certaines sources)"],["1947","Subbuteo est mis en vente en Grande-Bretagne"],["1962","Fondation d’une fédération de l’État de São Paulo"],["1988","Reconnu comme sport officiel au Brésil"]],"figL":{"rules":[["1","Bahia\ndisque"],["3","Rio\nballe"],["12","São Paulo\nballe"]],"family":[["Futebol de botão","Brésil · règlement de 1930"],["Gombfoci","Hongrie · boutons de manteau"],["Newfooty","Grande-Bretagne · 1929"],["Subbuteo","Grande-Bretagne · 1947 · figurines"],["Baby-foot","figurines sur barres · brevet de 1921"]]}}};
